      setState('ready');
    } catch (e) {
      setState('error');
      setError(e instanceof Error ? e.message : t('live.obsIngestLoadError'));
    }
  }, [token, t]);

  useEffect(() => {
    void loadIngest();
  }, [loadIngest]);

  const serverUrl =
    useRtmpFallback && creds?.rtmpUrl ? creds.rtmpUrl : creds?.rtmpsUrl ?? '';

  return (
