              </div>
              <span className="text-xs text-gray-500 pb-1.5">{goalUnit(goalForm.type)}</span>
            </div>
            <div>
              <p className="text-[10px] text-gray-400 mb-1">{t('live.setupGoalLabel')}</p>
              <input
                type="text"
