                  <input
                    type="number"
                    min="1"
                    max="100"
                    value={rewardForm.price}
                    onChange={(e) => setRewardForm((f) => ({ ...f, price: e.target.value }))}
                    className={`${fieldInputClass} px-1.5 text-center`}
                    aria-label={t('live.setupRewardMin')}
