import { useEffect, useRef, useState } from 'react';
import { getSocket } from '../lib/socket';
import { donTierEmoji, GIFT_EMOJI, LIVE_DON_TIERS } from '../lib/liveReactions';

interface GiftBurst {
  id: string;
  emoji: string;
  senderName: string;
  amount?: number;
  giftType: string;
}

interface LiveGiftOverlayProps {
  liveId: string;
  visible: boolean;
  tiers?: readonly number[];
  onOpenGiftSheet: (amount?: number) => void;
}

export function LiveGiftOverlay({
  liveId,
  visible,
  tiers = LIVE_DON_TIERS,
  onOpenGiftSheet,
}: LiveGiftOverlayProps) {
  const [pickerOpen, setPickerOpen] = useState(false);
  const [bursts, setBursts] = useState<GiftBurst[]>([]);
  const burstSeq = useRef(0);

  useEffect(() => {
    if (!visible) {
      setPickerOpen(false);
      return;
    }
    const socket = getSocket();
    if (!socket) return;
    const onGiftAnimation = (gift: {
      liveId: string;
      id?: string;
      senderName: string;
      giftType: string;
      amount?: number;
    }) => {
      if (gift.liveId !== liveId) return;
      const emoji =
        gift.giftType === 'don' && gift.amount
          ? donTierEmoji(gift.amount)
          : GIFT_EMOJI[gift.giftType] ?? '✨';
      const id = gift.id ?? `burst_${Date.now()}_${burstSeq.current++}`;
      setBursts((prev) => [
        ...prev.slice(-8),
        { id, emoji, senderName: gift.senderName, amount: gift.amount, giftType: gift.giftType },
      ]);
      window.setTimeout(() => {
        setBursts((prev) => prev.filter((b) => b.id !== id));
      }, 2600);
    };
    socket.on('gift_animation', onGiftAnimation);
    return () => {
      socket.off('gift_animation', onGiftAnimation);
    };
  }, [liveId, visible]);

  if (!visible) return null;

  const openTier = (amount: number) => {
    setPickerOpen(false);
    onOpenGiftSheet(amount);
  };

  return (
    <>
      <div className="absolute inset-0 z-[25] pointer-events-none overflow-hidden" aria-hidden>
        {bursts.map((burst, index) => (
          <div
            key={burst.id}
            className="live-gift-burst absolute right-4 flex flex-col items-center gap-0.5"
            style={{ bottom: `${4.5 + index * 0.35}rem` }}
          >
            <span className="text-3xl drop-shadow-[0_2px_8px_rgba(0,0,0,0.65)]">{burst.emoji}</span>
            <span className="max-w-[7rem] truncate rounded-full bg-black/55 px-2 py-0.5 text-[10px] font-bold text-white backdrop-blur-sm">
              {burst.senderName}
              {burst.giftType === 'don' && burst.amount ? ` · ${burst.amount} €` : ''}
            </span>
          </div>
        ))}
      </div>

      <div className="absolute bottom-14 right-3 z-30 flex flex-col items-end gap-2 pointer-events-auto">
        {pickerOpen && (
          <div className="live-gift-picker flex items-center gap-1.5 rounded-2xl border border-pink-500/35 bg-[#12121a]/95 p-1.5 shadow-xl backdrop-blur-md">
            {tiers.map((tier) => (
              <button
                key={tier}
                type="button"
                onClick={() => openTier(tier)}
                className="flex flex-col items-center justify-center min-w-[3.25rem] py-2 px-1.5 rounded-xl bg-pink-950/50 border border-pink-500/30 hover:border-pink-400 hover:bg-pink-900/40 active:scale-95 transition"
                aria-label={`Pourboire ${tier} euros`}
              >
                <span className="text-xl leading-none">{donTierEmoji(tier)}</span>
                <span className="text-[10px] font-bold text-pink-200 mt-0.5">{tier} €</span>
              </button>
            ))}
            <button
              type="button"
              onClick={() => {
                setPickerOpen(false);
                onOpenGiftSheet();
              }}
              className="flex h-[3.25rem] min-w-[2.75rem] items-center justify-center rounded-xl border border-[#2d2d3d] bg-[#1a1a26] text-[10px] font-bold text-gray-300 hover:border-white/20"
              aria-label="Autre montant"
            >
              ···
            </button>
          </div>
        )}

        <button
          type="button"
          onClick={() => setPickerOpen((o) => !o)}
          className={`flex h-12 w-12 items-center justify-center rounded-full border-2 shadow-lg backdrop-blur-md transition active:scale-95 ${
            pickerOpen
              ? 'bg-pink-600 border-pink-400 text-white shadow-pink-900/50'
              : 'bg-[#12121a]/90 border-pink-500/50 text-2xl shadow-black/40 hover:border-pink-400'
          }`}
          aria-label={pickerOpen ? 'Fermer les cadeaux' : 'Envoyer un pourboire'}
          aria-expanded={pickerOpen}
        >
          {pickerOpen ? '✕' : '💝'}
        </button>
      </div>
    </>
  );
}

import { useEffect, useMemo, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { useTranslation } from 'react-i18next';
import { useAnchoredPopoverPosition } from '../hooks/useAnchoredPopoverPosition';
import { useLiveHostSession } from '../hooks/useLiveHostSession';
import {
  type GoalProgressStats,
  withGoalsProgress,
} from '../lib/liveGoalProgress';
import type { LiveGoal, RewardQueueItem } from '../lib/liveHostTypes';

type LiveHostActionsPopoverProps = {
  liveId: string;
  goalStats: GoalProgressStats;
  panelAbove?: boolean;
  onOpenDonPanel?: (subTab: 'goals' | 'rewards') => void;
};

const POPOVER_TRIGGER_CLASS =
  'relative w-11 h-11 flex items-center justify-center rounded-lg transition text-sm leading-none touch-manipulation';

function goalUnit(type: LiveGoal['type']): string {
  switch (type) {
    case 'amount':
      return '€';
    case 'duration':
      return 'min';
    default:
      return '';
  }
}

function ActionRow({
  title,
  subtitle,
  note,
  badge,
  onValidate,
  onDelete,
  validateLabel,
  deleteLabel,
}: {
  title: string;
  subtitle: string;
  note?: string;
  badge: string;
  onValidate: () => void;
  onDelete: () => void;
  validateLabel: string;
  deleteLabel: string;
}) {
  return (
    <div className="rounded-lg border border-[#2a2a3a] bg-[#12121a] p-2.5">
      <div className="flex items-start gap-2 mb-2">
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-1.5 mb-0.5">
            <span className="shrink-0 text-[9px] font-black uppercase tracking-widest text-purple-300">
              {badge}
            </span>
          </div>
          <p className="text-xs font-bold text-white truncate">{title}</p>
          <p className="text-[10px] text-gray-500 truncate">{subtitle}</p>
          {note ? (
            <p className="text-[10px] text-purple-300 mt-0.5 italic truncate">&ldquo;{note}&rdquo;</p>
          ) : null}
        </div>
      </div>
      <div className="flex gap-1.5">
        <button
          type="button"
          onClick={onValidate}
          className="flex-1 min-h-9 py-1.5 rounded-lg bg-emerald-900/60 border border-emerald-500/40 text-emerald-300 text-[10px] font-bold hover:bg-emerald-900 transition touch-manipulation"
        >
          {validateLabel}
        </button>
        <button
          type="button"
          onClick={onDelete}
          className="flex-1 min-h-9 py-1.5 rounded-lg bg-[#1a1a26] border border-[#232330] text-gray-400 text-[10px] font-bold hover:text-red-400 hover:border-red-500/30 transition touch-manipulation"
        >
          {deleteLabel}
        </button>
      </div>
    </div>
  );
}

export function LiveHostActionsPopover({
  liveId,
  goalStats,
  panelAbove = false,
  onOpenDonPanel,
}: LiveHostActionsPopoverProps) {
  const { t } = useTranslation();
  const { session, update } = useLiveHostSession(liveId);
  const [open, setOpen] = useState(false);
  const panelRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  const goals = useMemo(
    () => withGoalsProgress(session.goals, goalStats).filter((g) => g.liveId === liveId),
    [session.goals, goalStats, liveId],
  );
  const activeGoals = goals.filter((g) => !g.completedAt);
  const rewardActions = session.rewardQueue.filter(
    (i) => i.status === 'pending' || i.status === 'accepted',
  );

  const todoCount = rewardActions.length + activeGoals.length;

  useEffect(() => {
    if (!open) return;
    const onDocClick = (e: MouseEvent) => {
      const target = e.target as Node;
      if (panelRef.current?.contains(target) || buttonRef.current?.contains(target)) return;
      setOpen(false);
    };
    document.addEventListener('mousedown', onDocClick);
    return () => document.removeEventListener('mousedown', onDocClick);
  }, [open]);

  const updateQueue = (id: string, status: RewardQueueItem['status']) =>
    update((prev) => ({
      rewardQueue: prev.rewardQueue.map((i) => (i.id === id ? { ...i, status } : i)),
    }));

  const completeGoal = (id: string) =>
    update((prev) => ({
      goals: prev.goals.map((g) => (g.id === id ? { ...g, completedAt: Date.now() } : g)),
    }));

  const removeGoal = (id: string) =>
    update((prev) => ({ goals: prev.goals.filter((g) => g.id !== id) }));

  const countLabel =
    todoCount === 0
      ? t('live.hostActionsCountNone')
      : t('live.hostActionsCount', { count: todoCount });

  const panelPos = useAnchoredPopoverPosition(open, buttonRef, panelRef, [
    todoCount,
    rewardActions.length,
    activeGoals.length,
  ], { estimatedWidth: 320, estimatedHeight: 320, preferAbove: panelAbove });

  const panel =
    open && typeof document !== 'undefined' ? (
      <div
        ref={panelRef}
        className="fixed z-[70] w-[min(20rem,calc(100vw-2rem))] rounded-xl border border-purple-500/30 bg-[#0e0e14] shadow-2xl overflow-hidden"
        style={{
          top: panelPos?.top ?? (buttonRef.current?.getBoundingClientRect().bottom ?? 0) + 4,
          left: panelPos?.left ?? 8,
          visibility: panelPos ? 'visible' : 'hidden',
        }}
      >
          <div className="px-3 py-2 border-b border-purple-500/20 bg-[#14101c]/90">
            <div className="flex items-center justify-between gap-2">
              <p className="text-[10px] text-gray-500 tabular-nums min-w-0 truncate">{countLabel}</p>
              <p className="text-[10px] font-bold text-purple-300 uppercase tracking-widest shrink-0">
                {t('live.hostActionsShort')}
              </p>
            </div>
          </div>

          <div className="p-2 space-y-2 max-h-72 overflow-y-auto">
            {todoCount === 0 ? (
              <p className="text-[11px] text-gray-500 px-1 py-2">{t('live.hostActionsEmpty')}</p>
            ) : null}

            {rewardActions.length > 0 ? (
              <div className="space-y-1.5">
                <p className="text-[9px] font-bold text-gray-500 uppercase tracking-widest px-0.5">
                  {t('live.hostActionsRewardsSection')}
                </p>
                {rewardActions.map((item) => (
                  <ActionRow
                    key={item.id}
                    badge={
                      item.status === 'accepted'
                        ? t('live.hostActionsRewardAccepted')
                        : t('live.hostActionsRewardPending')
                    }
                    title={item.rewardLabel}
                    subtitle={`${item.donorName} · ${item.amount}€`}
                    note={item.note}
                    validateLabel={t('live.hostActionsValidate')}
                    deleteLabel={t('live.hostActionsDelete')}
                    onValidate={() => updateQueue(item.id, 'done')}
                    onDelete={() => updateQueue(item.id, 'refused')}
                  />
                ))}
              </div>
            ) : null}

            {activeGoals.length > 0 ? (
              <div className="space-y-1.5">
                <p className="text-[9px] font-bold text-gray-500 uppercase tracking-widest px-0.5">
                  {t('live.hostActionsGoalsSection')}
                </p>
                {activeGoals.map((g) => {
                  const pct = Math.min(100, Math.round((g.current / g.target) * 100));
                  const ready = pct >= 100;
                  return (
                    <ActionRow
                      key={g.id}
                      badge={
                        ready
                          ? t('live.hostActionsGoalReady')
                          : t('live.hostActionsGoalProgress', { pct })
                      }
                      title={g.label}
                      subtitle={`${g.current} / ${g.target}${goalUnit(g.type) ? ` ${goalUnit(g.type)}` : ''}`}
                      validateLabel={t('live.hostActionsValidate')}
                      deleteLabel={t('live.hostActionsDelete')}
                      onValidate={() => completeGoal(g.id)}
                      onDelete={() => removeGoal(g.id)}
                    />
                  );
                })}
              </div>
            ) : null}
          </div>

          {onOpenDonPanel ? (
            <div className="px-2 pb-2 border-t border-[#1e1e2f] pt-2">
              <button
                type="button"
                onClick={() => {
                  onOpenDonPanel(rewardActions.length > 0 ? 'rewards' : 'goals');
                  setOpen(false);
                }}
                className="w-full min-h-9 py-2 rounded-lg bg-purple-900/40 border border-purple-500/30 text-purple-200 text-[10px] font-bold hover:bg-purple-900/60 transition touch-manipulation"
              >
                {t('live.hostActionsOpenDonPanel')}
              </button>
            </div>
          ) : null}
      </div>
    ) : null;

  return (
    <div className="relative shrink-0">
      <button
        ref={buttonRef}
        type="button"
        onClick={() => setOpen((v) => !v)}
        className={`${POPOVER_TRIGGER_CLASS} ${
          open
            ? 'text-purple-300 bg-purple-950/50'
            : todoCount > 0
              ? 'text-amber-300 hover:bg-white/10'
              : 'text-gray-500 hover:text-purple-300 hover:bg-white/10'
        }`}
        aria-label={t('live.hostActionsTodo')}
        aria-expanded={open}
        title={t('live.hostActionsTodo')}
      >
        <span aria-hidden>📋</span>
        {todoCount > 0 ? (
          <span className="absolute -top-0.5 -right-0.5 min-w-[18px] h-[18px] px-1 flex items-center justify-center rounded-full bg-amber-500 text-[9px] font-black text-black tabular-nums">
            {todoCount > 9 ? '9+' : todoCount}
          </span>
        ) : null}
      </button>

      {panel ? createPortal(panel, document.body) : null}
    </div>
  );
}

