/** Floating PiP preview for a live stream (HLS/WebRTC) — no join, no socket. */

import { useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import {
  useDraggableVideoPip,
  defaultVideoPipPos,
  VIDEO_PIP_WIDTH,
  VIDEO_PIP_HEADER_HEIGHT,
} from './DraggableVideoPip';
import { FollowUserButton } from './FollowUserButton';
import { useAuth } from '../context/AuthContext';
import { useCloudflareHlsPlayback } from '../hooks/useCloudflareHlsPlayback';
import { api } from '../lib/api';
import type { Live } from '../types';

function LivePipPreviewFloatInner({
  live,
  onJoin,
  onClose,
}: {
  live: Live;
  onJoin: () => void;
  onClose: () => void;
}) {
  const { token } = useAuth();
  const pip = useDraggableVideoPip(true, onClose, defaultVideoPipPos, live.id);
  const videoH = Math.round((VIDEO_PIP_WIDTH * 9) / 16);
  const [hostFollowing, setHostFollowing] = useState(false);

  useEffect(() => {
    if (!token) return;
    let cancelled = false;
    void api.getMyFollowing(token).then((r) => {
      if (!cancelled) setHostFollowing(r.followingIds.includes(live.hostId));
    });
    return () => {
      cancelled = true;
    };
  }, [token, live.hostId]);

  const isCloudflare = live.streamMode === 'cloudflare';
  const hls = useCloudflareHlsPlayback({
    playbackUrl: isCloudflare ? (live.cloudflarePlaybackUrl ?? null) : null,
    active: isCloudflare,
  });

  const albumArtUrl = live.playbackState.albumArtUrl;

  return createPortal(
    <div
      className="pointer-events-auto fixed rounded-xl overflow-hidden shadow-2xl border border-[#2a2a3a] bg-[#0b0b0f]"
      style={{ left: pip.position.x, top: pip.position.y, width: VIDEO_PIP_WIDTH, zIndex: 99999 }}
    >
      {/* Draggable header */}
      <div
        className="flex items-center gap-1.5 px-2 border-b border-[#2a2a36] bg-[#14141c]/95 cursor-grab active:cursor-grabbing select-none touch-none"
        style={{ height: VIDEO_PIP_HEADER_HEIGHT }}
        onPointerDown={pip.onHeaderPointerDown}
      >
        <span className="text-[10px] text-red-400/80 leading-none shrink-0" aria-hidden>⠿</span>
        <p className="flex-1 truncate min-w-0 text-[9px] font-bold text-red-400 uppercase tracking-widest">
          {live.title}
        </p>
        <div
          className="shrink-0"
          onPointerDown={(e) => e.stopPropagation()}
        >
          <FollowUserButton
            userId={live.hostId}
            username={live.hostName}
            initialFollowing={hostFollowing}
            iconOnly
            iconStyle="heart"
            onFollowingChange={setHostFollowing}
          />
        </div>
        <button
          type="button"
          onPointerDown={(e) => e.stopPropagation()}
          onClick={onJoin}
          className="shrink-0 px-2 py-0.5 rounded text-[9px] bg-red-600 hover:bg-red-500 text-white transition"
          title="Rejoindre le live"
        >
          Rejoindre
        </button>
        <button
          type="button"
          onPointerDown={(e) => e.stopPropagation()}
          onClick={onClose}
          className="shrink-0 w-5 h-5 flex items-center justify-center rounded text-gray-400 hover:text-white hover:bg-white/10 transition text-xs"
          aria-label="Fermer la prévisualisation"
        >
          ×
        </button>
      </div>

      {/* Video / placeholder */}
      {isCloudflare ? (
        <div className="relative bg-black" style={{ width: VIDEO_PIP_WIDTH, height: videoH }}>
          {/* HLS video always mounted so the ref callback can attach */}
          <video
            ref={hls.hlsVideoRef}
            autoPlay
            playsInline
            muted
            className="absolute inset-0 w-full h-full live-cloudflare-stage-video"
            style={{ opacity: hls.hlsStreamActive ? 1 : 0 }}
          />
          {!hls.hlsStreamActive && (
            <div className="absolute inset-0 flex flex-col items-center justify-center gap-1 text-gray-500">
              {albumArtUrl ? (
                <img src={albumArtUrl} alt="" className="w-10 h-10 rounded-lg object-cover opacity-60" />
              ) : (
                <span className="text-xl">📡</span>
              )}
              <p className="text-[10px]">
                {hls.hlsPhase === 'error' ? 'Flux indisponible' : 'Connexion…'}
              </p>
            </div>
          )}
          {hls.hlsPlaybackBlocked && hls.hlsStreamActive && (
            <button
              type="button"
              onClick={() => void hls.enableHlsPlayback()}
              className="absolute inset-0 flex items-center justify-center bg-black/60 text-white"
            >
              <span className="text-2xl">▶</span>
            </button>
          )}
        </div>
      ) : (
        /* WebRTC / unknown — no preview without joining */
        <div
          className="flex flex-col items-center justify-center gap-1.5 bg-black"
          style={{ width: VIDEO_PIP_WIDTH, height: videoH }}
        >
          {albumArtUrl ? (
            <img src={albumArtUrl} alt="" className="w-12 h-12 rounded-xl object-cover opacity-70" />
          ) : (
            <span className="text-2xl">📡</span>
          )}
          <p className="text-[10px] text-gray-500 text-center px-3">
            Rejoignez pour voir le live
          </p>
        </div>
      )}
    </div>,
    document.body
  );
}

export function LivePipPreviewFloat({
  live,
  onJoin,
  onClose,
}: {
  live: Live;
  onJoin: () => void;
  onClose: () => void;
}) {
  return <LivePipPreviewFloatInner live={live} onJoin={onJoin} onClose={onClose} />;
}

import { useEffect, useRef, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { api } from '../lib/api';
import { getSocket } from '../lib/socket';
import { UsernameDisplay } from './UsernameDisplay';
import type { DirectMessage, DmContact } from '../types';

interface LivePrivateSheetProps {
  target: DmContact;
  onClose: () => void;
  onOpenProfile?: (userId: string) => void;
}

export function LivePrivateSheet({ target, onClose, onOpenProfile }: LivePrivateSheetProps) {
  const { user, token } = useAuth();
  const [messages, setMessages] = useState<DirectMessage[]>([]);
  const [draft, setDraft] = useState('');
  const [sending, setSending] = useState(false);
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!token) return;
    api.getDmThread(token, target.id).then((r) => setMessages(r.messages));
  }, [token, target.id]);

  useEffect(() => {
    if (!token || !user) return;
    const socket = getSocket();
    if (!socket) return;
    const onDm = (msg: DirectMessage) => {
      if (
        (msg.senderId === user.id && msg.receiverId === target.id) ||
        (msg.senderId === target.id && msg.receiverId === user.id)
      ) {
        setMessages((m) => (m.some((x) => x.id === msg.id) ? m : [...m, msg]));
      }
    };
    socket.on('dm', onDm);
    return () => {
      socket.off('dm', onDm);
    };
  }, [token, user?.id, target.id]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const send = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!token || !draft.trim() || sending) return;
    setSending(true);
    const text = draft.trim();
    setDraft('');
    try {
      const { message } = await api.sendDm(token, target.id, text);
      setMessages((m) => [...m, message]);
    } catch (err) {
      alert(err instanceof Error ? err.message : 'Erreur envoi');
      setDraft(text);
    } finally {
      setSending(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60" onClick={onClose}>
      <div
        className="flex flex-col w-full max-w-md max-h-[70dvh] bg-[#12121a] rounded-2xl border border-[#2d2d3d] shadow-2xl"
        onClick={(e) => e.stopPropagation()}
      >
        <header className="shrink-0 flex items-center gap-3 p-4 border-b border-[#1e1e2f]">
          <img
            src={target.avatarUrl || `https://api.dicebear.com/7.x/adventurer/svg?seed=${target.id}`}
            alt=""
            className="w-10 h-10 rounded-full"
          />
          <div className="flex-1 min-w-0">
            {onOpenProfile ? (
              <button
                type="button"
                onClick={() => onOpenProfile(target.id)}
                className="font-bold text-white truncate text-left max-w-full hover:text-purple-300 transition-colors"
                title="Voir le profil"
              >
                <UsernameDisplay
                  username={target.username}
                  usernameColor={target.usernameColor}
                  usernameWaveFrom={target.usernameWaveFrom}
                  usernameWaveTo={target.usernameWaveTo}
                  className="truncate inline"
                />
              </button>
            ) : (
              <p className="font-bold text-white truncate">{target.username}</p>
            )}
            <p className="text-xs text-purple-400">Message privé (hors du chat public)</p>
          </div>
          <button type="button" onClick={onClose} className="text-gray-400 hover:text-white text-xl px-2">
            ✕
          </button>
        </header>

        <div className="flex-1 min-h-0 overflow-y-auto p-3 space-y-2 max-h-[40dvh]">
          {messages.length === 0 && (
            <p className="text-center text-gray-500 text-sm py-6">Premier message privé avec {target.username}</p>
          )}
          {messages.map((m) => {
            const isMe = m.senderId === user?.id;
            return (
              <div key={m.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}>
                <div
                  className={`max-w-[85%] rounded-2xl px-3 py-2 text-sm ${
                    isMe ? 'bg-purple-600/80 text-white' : 'bg-[#1a1a26] border border-[#2d2d3d] text-gray-100'
                  }`}
                >
                  {m.content}
                </div>
              </div>
            );
          })}
          <div ref={bottomRef} />
        </div>

        <form onSubmit={send} className="shrink-0 flex gap-2 p-3 border-t border-[#1e1e2f]">
          <input
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            placeholder="Message privé..."
            className="flex-1 bg-[#1a1a26] border border-[#2d2d3d] rounded-full px-4 py-2.5 text-sm text-white"
          />
          <button
            type="submit"
            disabled={!draft.trim() || sending}
            className="px-4 py-2.5 bg-purple-600 disabled:opacity-40 rounded-full font-bold text-white text-sm"
          >
            Envoyer
          </button>
        </form>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useRef, useState, type CSSProperties, type ReactNode } from 'react';
import { VIDEO_PIP_WIDTH, VIDEO_PIP_HEADER_HEIGHT, type VideoPipFloatApi } from './DraggableVideoPip';
import {
  LIVE_CAMERA_HOST_OBS_STOPPED,
  LIVE_CAMERA_VIEWER_AUDIO_BLOCKED,
  LIVE_CAMERA_VIEWER_CLOUDFLARE_WAITING_OBS,
  LIVE_CAMERA_VIEWER_FILE_NOTE,
  LIVE_CAMERA_VIEWER_NO_HOST_CAMERA,
  LIVE_CAMERA_VIEWER_NOTE,
  LIVE_CAMERA_VIEWER_VIDEO_PENDING,
  isHiddenHostTheaterStatus,
} from '../lib/liveCameraMessages';
import type { ViewerRelayPhase } from '../hooks/useLiveVideoRelay';
import type { HlsPlaybackPhase } from '../hooks/useCloudflareHlsPlayback';
