    const onViewChange = () => {
      const zoom = map.getZoom();
      flatMapZoomRef.current = zoom;
      if (zoom !== lastFlatZoomRef.current) {
        lastFlatZoomRef.current = zoom;
        setFlatMapZoom((prev) => (shouldCommitFlatMapZoom(prev, zoom) ? zoom : prev));
