      scheduleDetailEmit();
      if (!zoomSliderDraggingRef.current && flatRevealRef.current >= 0.5) {
        syncZoomControlFromViewRef.current();
      }
      if (flatRevealRef.current >= 0.5 && getFlatMapDetailTier(zoom) !== 'overview') {
