import { useCallback, useEffect, useRef, useState } from 'react';
import { api } from '../lib/api';
import { isPlatformConnected } from '../lib/platformConnect';
import { PLATFORM_STATUS_REFRESH_EVENT } from '../lib/platformStatusEvents';
import { STORAGE_KEYS } from '../lib/storageKeys';
import { PlatformConnectCard } from './PlatformConnectCard';
import type { User } from '../types';

const DISMISS_KEY = STORAGE_KEYS.platformPromptDismissed;
const LEGACY_DISMISS_KEY = 'soundly_platform_prompt_dismissed';

function isPlatformPromptDismissed(): boolean {
  try {
    if (sessionStorage.getItem(DISMISS_KEY) === '1') return true;
    if (sessionStorage.getItem(LEGACY_DISMISS_KEY) === '1') {
      sessionStorage.setItem(DISMISS_KEY, '1');
      sessionStorage.removeItem(LEGACY_DISMISS_KEY);
      return true;
    }
  } catch {
    /* ignore */
  }
  return false;
}

function hasStreamingPlatformConnected(user: User): boolean {
  return isPlatformConnected(user.connectedPlatforms, 'youtube');
}

function statusHasStreamingPlatform(
  connectedPlatforms: User['connectedPlatforms'] | undefined
): boolean {
  return isPlatformConnected(connectedPlatforms, 'youtube');
}

interface PlatformConnectPromptProps {
  token: string;
  user: User;
  onUserUpdated: (user: User) => void;
  onOpenProfile?: () => void;
}

export function PlatformConnectPrompt({
  token,
  user,
  onUserUpdated,
  onOpenProfile,
}: PlatformConnectPromptProps) {
  const [visible, setVisible] = useState(false);
  const [expanded, setExpanded] = useState(false);
  const [oauthConfigured, setOauthConfigured] = useState(false);

  const userRef = useRef(user);
  userRef.current = user;

  const evaluate = useCallback((fresh = false) => {
    if (isPlatformPromptDismissed()) {
      setVisible(false);
      return;
    }
    if (hasStreamingPlatformConnected(userRef.current)) {
      setVisible(false);
      return;
    }
    api
      .getPlatformStatus(token, fresh ? { fresh: true } : undefined)
      .then((s) => {
        const required = s.platformConnectionRequired ?? s.oauthConfigured ?? false;
        const connected =
          Boolean(s.hasRealPlatformConnection) || statusHasStreamingPlatform(s.connectedPlatforms);
        setOauthConfigured(required);
        setVisible(required && !connected);
      })
      .catch(() => setVisible(false));
  }, [token]);

  useEffect(() => {
    evaluate();
  }, [evaluate, user.connectedPlatforms]);

  useEffect(() => {
    const onRefresh = () => evaluate(true);
    window.addEventListener(PLATFORM_STATUS_REFRESH_EVENT, onRefresh);
    return () => window.removeEventListener(PLATFORM_STATUS_REFRESH_EVENT, onRefresh);
  }, [evaluate]);

  if (!visible) return null;

  const dismiss = () => {
    sessionStorage.setItem(DISMISS_KEY, '1');
    setVisible(false);
  };

  return (
    <div className="mx-3 mt-2 mb-1 rounded-xl border border-purple-500/30 bg-purple-500/10 p-3">
      <div className="flex items-start justify-between gap-2">
        <div>
          <p className="text-sm font-bold text-white">Connecte YouTube</p>
          <p className="text-[11px] text-gray-400 mt-0.5 leading-snug">
            YouTube est requis pour héberger des salons avec ta bibliothèque.
          </p>
        </div>
        <button
          type="button"
          onClick={dismiss}
          className="text-gray-500 hover:text-gray-300 text-xs shrink-0 px-1"
          aria-label="Masquer"
        >
          ×
        </button>
      </div>
      <div className="mt-3 flex flex-wrap gap-2">
        <button
          type="button"
          onClick={() => setExpanded((v) => !v)}
          className="px-3 py-1.5 rounded-lg text-xs font-semibold bg-purple-600 text-white hover:bg-purple-500"
        >
          {expanded ? 'Masquer les boutons' : 'Connecter maintenant'}
        </button>
        {onOpenProfile ? (
          <button
            type="button"
            onClick={onOpenProfile}
            className="px-3 py-1.5 rounded-lg text-xs text-gray-300 border border-[#2d2d3d] hover:text-white"
          >
            Ouvrir mon profil
          </button>
        ) : null}
      </div>
      {expanded ? (
        <div className="mt-3 space-y-2">
          {(['youtube'] as const).map((p) => (
            <PlatformConnectCard
              key={p}
              token={token}
              platform={p}
              connectedPlatforms={user.connectedPlatforms}
              onUserUpdated={(u) => {
                onUserUpdated(u);
                if (hasStreamingPlatformConnected(u)) {
                  setVisible(false);
                } else if (oauthConfigured) {
                  evaluate(true);
                }
              }}
            />
          ))}
        </div>
      ) : null}
    </div>
  );
}

import type { MusicPlatform } from '../lib/platformConnect';

interface PlatformListeningIconProps {
