  const lastSeekAtRef = useRef(0);
  const lastParticipantSyncTriggerRef = useRef<number | undefined>(undefined);

  const floatActive = Boolean(videoFloat);
  const pauseAndMutePlayer = useCallback((player: YTPlayerInstance) => {
    try {
      player.pauseVideo();
      player.mute();
