    const sizeEl = sizeRef.current;
    const initialW = Math.max(1, Math.round(sizeEl?.clientWidth ?? 640));
    const initialH = Math.max(1, Math.round(sizeEl?.clientHeight ?? 360));
    new window.YT!.Player(containerRef.current, {
      videoId,
      width: initialW,
      height: initialH,
      playerVars: {
