import { useCallback, useEffect, useRef, useState } from 'react';
import {
  bitmapCropToProfileDataUrl,
  computeCropRectFromViewport,
  initialCoverScale,
} from '../lib/profileImageProcessing';
import {
  bitmapCropToFeedDataUrl,
  bitmapCropToStoryDataUrl,
  computeStoryCropRect,
  FEED_VIEWPORT_H,
  FEED_VIEWPORT_W,
  initialFeedCoverScale,
  initialStoryCoverScale,
  loadImageBitmapFromDataUrl,
  loadImageBitmapFromFile,
  PROFILE_VIEWPORT_PX,
  STORY_VIEWPORT_H,
  STORY_VIEWPORT_W,
} from '../lib/storyImageCompose';

export type PhotoCropAspect = 'story' | 'profile' | 'feed';

interface StoryImageCropModalProps {
  source: File | string;
  aspect?: PhotoCropAspect;
  onConfirm: (dataUrl: string) => void;
  onCancel: () => void;
}

export function StoryImageCropModal({
  source,
  aspect = 'story',
  onConfirm,
  onCancel,
}: StoryImageCropModalProps) {
  const isProfile = aspect === 'profile';
  const isFeed = aspect === 'feed';
  const viewportW = isProfile ? PROFILE_VIEWPORT_PX : isFeed ? FEED_VIEWPORT_W : STORY_VIEWPORT_W;
  const viewportH = isProfile ? PROFILE_VIEWPORT_PX : isFeed ? FEED_VIEWPORT_H : STORY_VIEWPORT_H;
  const [bitmap, setBitmap] = useState<ImageBitmap | null>(null);
  const [scale, setScale] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [exporting, setExporting] = useState(false);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const dragRef = useRef<{ startX: number; startY: number; baseX: number; baseY: number } | null>(null);

  useEffect(() => {
    if (typeof source === 'string') {
      setPreviewUrl(source);
      return;
    }
    const url = URL.createObjectURL(source);
    setPreviewUrl(url);
    return () => URL.revokeObjectURL(url);
  }, [source]);

  useEffect(() => {
    let cancelled = false;
    let loaded: ImageBitmap | null = null;
    setLoading(true);
    setError(null);
    const load =
      typeof source === 'string'
        ? loadImageBitmapFromDataUrl(source)
        : loadImageBitmapFromFile(source);
    void load
      .then((bmp) => {
        if (cancelled) {
          bmp.close();
          return;
        }
        loaded = bmp;
        const base = isProfile
          ? initialCoverScale(bmp.width, bmp.height, PROFILE_VIEWPORT_PX)
          : isFeed
            ? initialFeedCoverScale(bmp.width, bmp.height)
            : initialStoryCoverScale(bmp.width, bmp.height);
        setBitmap(bmp);
        setScale(base);
        setOffset({ x: 0, y: 0 });
      })
      .catch((e) => {
        if (!cancelled) setError(e instanceof Error ? e.message : 'Image invalide');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
      loaded?.close();
    };
  }, [source, isProfile, isFeed]);

  useEffect(() => {
    return () => {
      bitmap?.close();
    };
  }, [bitmap]);

  const onPointerDown = (e: React.PointerEvent) => {
    if (!bitmap) return;
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    dragRef.current = {
      startX: e.clientX,
      startY: e.clientY,
      baseX: offset.x,
      baseY: offset.y,
    };
  };

  const onPointerMove = (e: React.PointerEvent) => {
    const d = dragRef.current;
    if (!d) return;
    setOffset({
      x: d.baseX + (e.clientX - d.startX),
      y: d.baseY + (e.clientY - d.startY),
    });
  };

  const onPointerUp = () => {
    dragRef.current = null;
  };

  const confirm = useCallback(() => {
    if (!bitmap) return;
    setExporting(true);
    try {
      const crop = isProfile
        ? computeCropRectFromViewport(
            bitmap.width,
            bitmap.height,
            PROFILE_VIEWPORT_PX,
            scale,
            offset.x,
            offset.y
          )
        : computeStoryCropRect(
            bitmap.width,
            bitmap.height,
            viewportW,
            viewportH,
            scale,
            offset.x,
            offset.y
          );
      const dataUrl = isProfile
        ? bitmapCropToProfileDataUrl(bitmap, crop)
        : isFeed
          ? bitmapCropToFeedDataUrl(bitmap, crop)
          : bitmapCropToStoryDataUrl(bitmap, crop);
      onConfirm(dataUrl);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Rognage impossible');
    } finally {
      setExporting(false);
    }
  }, [bitmap, scale, offset, onConfirm, isProfile, isFeed, viewportW, viewportH]);

  const minScale = bitmap
    ? isProfile
      ? initialCoverScale(bitmap.width, bitmap.height, PROFILE_VIEWPORT_PX)
      : isFeed
        ? initialFeedCoverScale(bitmap.width, bitmap.height)
        : initialStoryCoverScale(bitmap.width, bitmap.height)
    : 1;
  const maxScale = minScale * 4;

  return (
    <div
      className="fixed inset-0 z-[130] flex items-center justify-center bg-black/85 p-4"
      role="dialog"
      aria-modal="true"
      aria-labelledby="story-crop-title"
    >
      <div className="w-full max-w-sm bg-[#12121a] border border-[#2d2d3d] rounded-2xl p-4 space-y-4 shadow-2xl">
        <h2 id="story-crop-title" className="text-lg font-bold text-white text-center">
          Rogner la photo
        </h2>
        <p className="text-xs text-gray-400 text-center">
          Glissez pour repositionner · curseur pour zoomer
        </p>

        {loading && <p className="text-center text-gray-500 text-sm py-16">Chargement…</p>}
        {error && <p className="text-center text-red-400 text-sm">{error}</p>}

        {!loading && bitmap && (
          <>
            <div
              className="relative mx-auto rounded-xl overflow-hidden border-2 border-purple-500/50 bg-[#0b0b0f] touch-none select-none"
              style={{ width: viewportW, height: viewportH }}
              onPointerDown={onPointerDown}
              onPointerMove={onPointerMove}
              onPointerUp={onPointerUp}
              onPointerCancel={onPointerUp}
            >
              {previewUrl && (
                <img
                  src={previewUrl}
                  alt=""
                  draggable={false}
                  className="absolute max-w-none pointer-events-none"
                  style={{
                    width: bitmap.width * scale,
                    height: bitmap.height * scale,
                    left: (viewportW - bitmap.width * scale) / 2 + offset.x,
                    top: (viewportH - bitmap.height * scale) / 2 + offset.y,
                  }}
                />
              )}
              <div
                className="absolute inset-0 pointer-events-none ring-2 ring-inset ring-white/30"
                aria-hidden
              />
            </div>

            <label className="block">
              <span className="text-xs text-gray-400">Zoom</span>
              <input
                type="range"
                min={minScale}
                max={maxScale}
                step={0.01}
                value={scale}
                onChange={(e) => setScale(Number(e.target.value))}
                className="w-full mt-1 accent-purple-500"
              />
            </label>
          </>
        )}

        <div className="flex gap-2">
          <button
            type="button"
            onClick={onCancel}
            className="flex-1 py-3 rounded-xl border border-[#2d2d3d] text-gray-300 font-semibold text-sm"
          >
            Annuler
          </button>
          <button
            type="button"
            onClick={confirm}
            disabled={!bitmap || loading || exporting || Boolean(error)}
            className="flex-1 py-3 rounded-xl bg-purple-600 hover:bg-purple-500 text-white font-bold text-sm disabled:opacity-50"
          >
            {exporting ? '…' : 'Utiliser'}
          </button>
        </div>
      </div>
    </div>
  );
}

import type { CSSProperties, MouseEvent, PointerEvent } from 'react';
import { dispatchStoryAppLink, parseStoryAppLink } from '../lib/storyAppLink';
import { storyLinkDisplayLabel } from '../lib/storyLink';
import type { StoryLink } from '../types';

function IconLinkSmall() {
  return (
    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" aria-hidden className="shrink-0">
      <path
        d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
      />
      <path
        d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
      />
    </svg>
  );
}

function IconMusicSmall() {
  return (
    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" aria-hidden className="shrink-0">
      <path d="M9 18V5l12-2v13" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
      <circle cx="6" cy="18" r="3" stroke="currentColor" strokeWidth="2" />
      <circle cx="18" cy="16" r="3" stroke="currentColor" strokeWidth="2" />
    </svg>
  );
}

export function storyLinkStickerStyle(
  x: number,
  y: number,
  isActive = false
): CSSProperties {
  return {
    left: `${x * 100}%`,
    top: `${y * 100}%`,
    transform: 'translate(-50%, -50%)',
    boxShadow: isActive ? '0 0 0 2px rgba(168,85,247,0.9)' : undefined,
  };
}

interface StoryLinkStickerProps {
  link: Pick<StoryLink, 'url' | 'label'>;
  isActive?: boolean;
  className?: string;
  onPointerDown?: (e: PointerEvent) => void;
  onClick?: (e: MouseEvent) => void;
}

export function StoryLinkSticker({
  link,
  isActive = false,
  className = '',
  onPointerDown,
  onClick,
}: StoryLinkStickerProps) {
  const label = storyLinkDisplayLabel(link);
  const previewOnly = !link.url.trim();
  const isAppLink = Boolean(link.url.trim() && parseStoryAppLink(link.url));

  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-full px-3 py-1.5 text-[11px] font-semibold shadow-[0_2px_10px_rgba(0,0,0,0.35)] whitespace-nowrap max-w-[min(72vw,240px)] truncate ${
        isAppLink
          ? 'bg-gradient-to-r from-purple-600 to-fuchsia-500 text-white'
          : 'bg-white/95 text-[#111111]'
      } ${className}`}
      onPointerDown={onPointerDown}
      onClick={onClick}
      style={isActive ? { boxShadow: '0 0 0 2px rgba(168,85,247,0.9)' } : undefined}
    >
      {isAppLink ? <IconMusicSmall /> : <IconLinkSmall />}
      <span className="truncate">{previewOnly ? 'Lien' : label}</span>
      <svg
        width="10"
        height="10"
        viewBox="0 0 24 24"
        fill="none"
        aria-hidden
        className="shrink-0 opacity-70"
      >
        <path
          d="M18 15l-6-6-6 6"
          stroke="currentColor"
          strokeWidth="2.5"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
    </span>
  );
}

interface StoryLinkOverlayProps {
  link: StoryLink;
  isActive?: boolean;
  interactive?: 'drag' | 'open' | 'none';
  onPointerDown?: (e: PointerEvent) => void;
}

export function StoryLinkOverlay({
  link,
  isActive = false,
  interactive = 'none',
  onPointerDown,
}: StoryLinkOverlayProps) {
  const style = storyLinkStickerStyle(link.x, link.y, isActive);
  const cursor =
    interactive === 'drag'
      ? 'cursor-grab active:cursor-grabbing'
      : interactive === 'open'
        ? 'cursor-pointer'
        : '';

  const handleOpen = (e: MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    const appTarget = parseStoryAppLink(link.url);
    if (appTarget) {
      dispatchStoryAppLink(appTarget);
      return;
    }
    window.open(link.url, '_blank', 'noopener,noreferrer');
  };

  if (interactive === 'open') {
    const appTarget = parseStoryAppLink(link.url);
    if (appTarget) {
      return (
        <button
          type="button"
          className={`absolute z-20 ${cursor}`}
          style={style}
          onClick={handleOpen}
          onPointerDown={(e) => e.stopPropagation()}
          aria-label={`Ouvrir : ${storyLinkDisplayLabel(link)}`}
        >
          <StoryLinkSticker link={link} />
        </button>
      );
    }
    return (
      <a
        href={link.url}
        target="_blank"
        rel="noopener noreferrer"
        className={`absolute z-20 ${cursor}`}
        style={style}
        onClick={handleOpen}
        onPointerDown={(e) => e.stopPropagation()}
        aria-label={`Ouvrir le lien : ${storyLinkDisplayLabel(link)}`}
      >
        <StoryLinkSticker link={link} />
      </a>
    );
  }

  return (
    <div
      className={`absolute z-[3] ${cursor} ${isActive ? 'z-10' : ''}`}
      style={style}
      onPointerDown={onPointerDown}
      onClick={(e) => e.stopPropagation()}
    >
      <StoryLinkSticker link={link} isActive={isActive} />
    </div>
  );
}

