import { useCallback, useEffect, useMemo, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { api } from '../lib/api';
import {
  getLivesGeo,
  MAP_GEO_CHANGED_EVENT,
  type LivesGeoPrefs,
} from '../lib/livesGeo';
import {
  getLiveMediaDraft,
  getLiveMediaPrefs,
  clearLiveMediaDraft,
} from '../lib/liveMediaPrefs';
import { setStripeConnectSkipped, clearStripeConnectSkipped } from '../lib/stripeConnectSkip';
import { isLiveStripeSetupPreviewMode } from '../lib/liveStripeDevSetup';

export interface UseStartLiveFlowOptions {
  onOpenLive: (liveId: string) => void;
  hasActiveSalon?: boolean;
  isActive?: boolean;
  /** Geo par défaut pour le modal média (ex. centre carte). */
  initialGeo?: LivesGeoPrefs;
}

export function useStartLiveFlow({
  onOpenLive,
  hasActiveSalon = false,
  isActive = true,
  initialGeo,
}: UseStartLiveFlowOptions) {
  const { token, user, setUserFromProfile, refreshUser } = useAuth();
  const [starting, setStarting] = useState(false);
  const [startError, setStartError] = useState<string | null>(null);
  const [mediaSetupOpen, setMediaSetupOpen] = useState(false);
  const [mediaSetupGeneration, setMediaSetupGeneration] = useState(0);
  const [legalGateOpen, setLegalGateOpen] = useState(false);
  const [geo, setGeo] = useState<LivesGeoPrefs>(() => initialGeo ?? getLivesGeo());

  const [stripeChecked, setStripeChecked] = useState(false);
  const [stripeSimulation, setStripeSimulation] = useState(false);
  const [donationsPlatformEnabled, setDonationsPlatformEnabled] = useState(false);
  const [stripeConnectReady, setStripeConnectReady] = useState(false);
  const [stripeChargesEnabled, setStripeChargesEnabled] = useState<boolean | null>(null);
  /** Choix explicite « live sans pourboires » dans le setup Lya (session courante). */
  const [liveTipsSkipped, setLiveTipsSkipped] = useState(false);

  const resolvedGeo = useMemo(
    () => initialGeo ?? geo,
    [geo, initialGeo]
  );

  useEffect(() => {
    if (initialGeo) setGeo(initialGeo);
  }, [initialGeo?.latitude, initialGeo?.longitude, initialGeo?.label, initialGeo?.source]);

  const verifyStripeForLiveSetup = useCallback(async () => {
    if (!token) return;
    setStripeChecked(false);
    try {
      const config = await api.getDonationsConfig(token);
      setStripeSimulation(config.simulation ?? false);
      setDonationsPlatformEnabled(config.enabled === true);
      const previewStripeSetup = isLiveStripeSetupPreviewMode();
      if (config.simulation && !previewStripeSetup) {
        setStripeConnectReady(true);
        setStripeChargesEnabled(true);
        return;
      }
      if (config.simulation && previewStripeSetup && !config.stripeConfigured) {
        setStripeConnectReady(false);
        setStripeChargesEnabled(null);
        return;
      }
      const status = await api.getStripeConnectStatus(token);
      setStripeConnectReady(status.ready === true);
      setStripeChargesEnabled(status.chargesEnabled ?? null);
      await refreshUser();
    } catch {
      setStripeConnectReady(false);
      setStripeChargesEnabled(null);
    } finally {
      setStripeChecked(true);
    }
  }, [refreshUser, token]);

  useEffect(() => {
    if (!isActive || !token) return;
    void verifyStripeForLiveSetup();
  }, [isActive, token, mediaSetupOpen, verifyStripeForLiveSetup]);

  useEffect(() => {
    const syncGeo = () => setGeo(getLivesGeo());
    window.addEventListener(MAP_GEO_CHANGED_EVENT, syncGeo);
    return () => window.removeEventListener(MAP_GEO_CHANGED_EVENT, syncGeo);
  }, []);

  const launchLiveAfterSetup = useCallback(async () => {
    if (!token) return;
    setStarting(true);
    try {
      const prefs = getLiveMediaPrefs() ?? getLiveMediaDraft();
      const lat = prefs?.startLatitude ?? resolvedGeo.latitude;
      const lon = prefs?.startLongitude ?? resolvedGeo.longitude;
      const skipped = liveTipsSkipped;
      const title =
        prefs?.liveTitle?.trim() || `Live — ${user?.username ?? 'Live'}`;
      const { live } = await api.startLive(token, title, {
        latitude: lat,
        longitude: lon,
        stripeConnectSkipped: skipped || undefined,
        useObs: prefs?.useObs || undefined,
        contentCategory: prefs?.contentCategory,
      });
      clearLiveMediaDraft();
      setMediaSetupGeneration((g) => g + 1);
      onOpenLive(live.id);
    } catch (e) {
      setStartError(e instanceof Error ? e.message : 'Impossible de démarrer le live');
    } finally {
      setStarting(false);
    }
  }, [liveTipsSkipped, onOpenLive, resolvedGeo.latitude, resolvedGeo.longitude, token, user?.username]);

  const proceedToMediaSetup = useCallback(() => {
    setLegalGateOpen(false);
    setMediaSetupOpen(true);
  }, []);

  const refreshStripeStatus = useCallback(async () => {
    await verifyStripeForLiveSetup();
  }, [verifyStripeForLiveSetup]);

  const handleStripeConnectSkip = useCallback(() => {
    setLiveTipsSkipped(true);
    setStripeConnectSkipped();
  }, []);

  const handleTipsAccepted = useCallback(() => {
    setLiveTipsSkipped(false);
    clearStripeConnectSkipped();
  }, []);

  const startLive = useCallback(() => {
    if (!token || starting) return;

    if (hasActiveSalon) {
      setStartError('Tu es déjà dans un salon. Quitte le salon pour démarrer un live.');
      return;
    }

    if (!user?.liveTermsAcceptedAt) {
      setLegalGateOpen(true);
      return;
    }

    setLiveTipsSkipped(false);
    clearStripeConnectSkipped();
    setMediaSetupOpen(true);
  }, [hasActiveSalon, starting, token, user?.liveTermsAcceptedAt]);

  const dismissStartError = useCallback(() => setStartError(null), []);

  return {
    token,
    user,
    setUserFromProfile,
    starting,
    startError,
    dismissStartError,
    startLive,
    mediaSetupOpen,
    setMediaSetupOpen,
    mediaSetupGeneration,
    launchLiveAfterSetup,
    geo: resolvedGeo,
    handleStripeConnectSkip,
    handleTipsAccepted,
    liveTipsSkipped,
    refreshStripeStatus,
    legalGateOpen,
    setLegalGateOpen,
    proceedToMediaSetup,
    stripeSimulation,
    donationsPlatformEnabled,
    stripeConnectReady,
    stripeChargesEnabled,
    stripeChecked,
  };
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { api } from '../lib/api';
import { mapApiItemToReelsSponsorAd } from '../lib/reelsSponsorFeed';
import {
  buildStoryViewerTimeline,
  DEFAULT_STORIES_SPONSOR_CONFIG,
  timelineIndexForSponsorKey,
  timelineIndexForStory,
  type StoriesSponsorConfig,
  type StoryViewerTimelineItem,
} from '../lib/storiesSponsorFeed';
import type { MapStory } from '../types';
import type { StoryUserStack } from '../lib/storyViewerNav';
import { findStackForStory, resolveNextStory, resolvePrevStory, stackIndexForStory } from '../lib/storyViewerNav';
import type { ReelsSponsorAd } from '../types';

export type StoryViewerSheetState =
  | { kind: 'closed' }
  | { kind: 'view'; story: MapStory; isOwn: boolean }
  | { kind: 'view_sponsor'; ad: ReelsSponsorAd; sponsorKey: string };

/** État visionneur élargi (ex. « create » sur la carte). */
export type StoryViewerSheetStateLike = StoryViewerSheetState | { kind: 'create' };

export function useStoryViewerWithSponsors(
  storyStacks: StoryUserStack[],
  viewerUserId: string | undefined,
  sheet: StoryViewerSheetStateLike,
  setSheet: (next: StoryViewerSheetState) => void,
  markStoryAsSeen: (storyId: string) => void
) {
  const [sponsorAds, setSponsorAds] = useState<ReelsSponsorAd[]>([]);
  const [sponsorConfig, setSponsorConfig] = useState<StoriesSponsorConfig>(
    DEFAULT_STORIES_SPONSOR_CONFIG
  );
  const frozenStacksRef = useRef<StoryUserStack[] | null>(null);

  const isViewing = sheet.kind === 'view' || sheet.kind === 'view_sponsor';

  useEffect(() => {
    if (!isViewing) {
      frozenStacksRef.current = null;
      return;
    }
    if (frozenStacksRef.current === null) {
      frozenStacksRef.current = storyStacks;
    }
  }, [isViewing, storyStacks]);

  const navStacks =
    isViewing && frozenStacksRef.current && frozenStacksRef.current.length > 0
      ? frozenStacksRef.current
      : storyStacks;

  useEffect(() => {
    let cancelled = false;
    void api
      .getStoriesViewerSponsors()
      .then((res) => {
        if (cancelled) return;
        setSponsorAds(res.items.map(mapApiItemToReelsSponsorAd));
        setSponsorConfig({
          storiesSponsorEnabled: res.config.storiesSponsorEnabled,
          storiesSponsorEveryN: res.config.storiesSponsorEveryN,
        });
      })
      .catch(() => {
        if (!cancelled) {
          setSponsorAds([]);
          setSponsorConfig(DEFAULT_STORIES_SPONSOR_CONFIG);
        }
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const timeline = useMemo(
    () => buildStoryViewerTimeline(navStacks, sponsorAds, sponsorConfig, viewerUserId),
    [navStacks, sponsorAds, sponsorConfig, viewerUserId]
  );

  const currentTimelineIndex = useMemo(() => {
    if (sheet.kind === 'view') return timelineIndexForStory(timeline, sheet.story.id);
    if (sheet.kind === 'view_sponsor') return timelineIndexForSponsorKey(timeline, sheet.sponsorKey);
    return -1;
  }, [sheet, timeline]);

  const applyTimelineItem = useCallback(
    (item: StoryViewerTimelineItem) => {
      if (item.kind === 'story') {
        markStoryAsSeen(item.story.id);
        setSheet({ kind: 'view', story: item.story, isOwn: item.isOwn });
        return;
      }
      setSheet({ kind: 'view_sponsor', ad: item.ad, sponsorKey: item.key });
    },
    [markStoryAsSeen, setSheet]
  );

  const goNextStory = useCallback(() => {
    if (sheet.kind !== 'view' && sheet.kind !== 'view_sponsor') return;
    const idx = currentTimelineIndex;
    if (idx >= 0 && idx < timeline.length - 1) {
      applyTimelineItem(timeline[idx + 1]!);
      return;
    }
    if (sheet.kind === 'view') {
      const next = resolveNextStory(navStacks, sheet.story, viewerUserId);
      if (next) {
        markStoryAsSeen(next.story.id);
        setSheet({ kind: 'view', story: next.story, isOwn: next.isOwn });
      }
    }
  }, [
    sheet,
    currentTimelineIndex,
    timeline,
    applyTimelineItem,
    navStacks,
    viewerUserId,
    markStoryAsSeen,
    setSheet,
  ]);

  const goPrevStory = useCallback(() => {
    if (sheet.kind !== 'view' && sheet.kind !== 'view_sponsor') return;
    const idx = currentTimelineIndex;
    if (idx > 0) {
      applyTimelineItem(timeline[idx - 1]!);
      return;
    }
    if (sheet.kind === 'view') {
      const prev = resolvePrevStory(navStacks, sheet.story, viewerUserId);
      if (prev) {
        markStoryAsSeen(prev.story.id);
        setSheet({ kind: 'view', story: prev.story, isOwn: prev.isOwn });
      }
    }
  }, [
    sheet,
    currentTimelineIndex,
    timeline,
    applyTimelineItem,
    navStacks,
    viewerUserId,
    markStoryAsSeen,
    setSheet,
  ]);

  const canNextStory =
    (sheet.kind === 'view' || sheet.kind === 'view_sponsor') &&
    (currentTimelineIndex >= 0
      ? currentTimelineIndex < timeline.length - 1
      : sheet.kind === 'view' && resolveNextStory(navStacks, sheet.story, viewerUserId) != null);

  const canPrevStory =
    (sheet.kind === 'view' || sheet.kind === 'view_sponsor') &&
    (currentTimelineIndex > 0 ||
      (sheet.kind === 'view' && resolvePrevStory(navStacks, sheet.story, viewerUserId) != null));

  const viewerStack =
    sheet.kind === 'view' ? findStackForStory(navStacks, sheet.story) : undefined;
  const viewerStackIndex =
    sheet.kind === 'view' && viewerStack ? stackIndexForStory(viewerStack, sheet.story) : 0;

  return {
    goNextStory,
    goPrevStory,
    canNextStory,
    canPrevStory,
    viewerStack,
    viewerStackIndex,
    sponsorAd: sheet.kind === 'view_sponsor' ? sheet.ad : undefined,
  };
}

