import type { MusicPlatform } from './salonPlayback';

export type { MusicPlatform };

/** Plateformes liables au profil (streaming + Instagram). */
export type ConnectPlatform = MusicPlatform | 'instagram';

export type PlatformLinkSummary = {
  platform: ConnectPlatform;
  isRealOAuth?: boolean;
};

export function isPlatformConnected(
  connectedPlatforms: MusicPlatform[] | undefined,
  platform: ConnectPlatform,
  platformLinks?: Array<PlatformLinkSummary> | undefined
): boolean {
  if (platform === 'instagram') {
    return Boolean(platformLinks?.some((l) => l.platform === 'instagram'));
  }
  return (connectedPlatforms ?? []).includes(platform);
}

/** OAuth réel pour YouTube. */
export function isRealMusicPlatformConnected(
  platform: MusicPlatform,
  links: Array<PlatformLinkSummary> | undefined
): boolean {
  return Boolean(links?.some((l) => l.platform === platform && l.isRealOAuth));
}

/** État « Connecté » profil / bannière — OAuth réel ou lien YouTube mock. */
export function isProfilePlatformConnected(
  platform: ConnectPlatform,
  platformLinks: Array<PlatformLinkSummary> | undefined
): boolean {
  if (platform === 'instagram') {
    return Boolean(platformLinks?.some((l) => l.platform === 'instagram'));
  }
  if (platform === 'youtube') {
    return Boolean(platformLinks?.some((l) => l.platform === 'youtube'));
  }
  return isRealMusicPlatformConnected(platform, platformLinks);
}

/** OAuth réel YouTube — requis pour héberger un salon avec sa bibliothèque. */
export function hasRealMusicPlatformLink(
  links: Array<PlatformLinkSummary> | undefined
): boolean {
  return (links ?? []).some(
    (l) => l.isRealOAuth && l.platform === 'youtube'
  );
}

/** OAuth réel requis pour créer / héberger / rejoindre un salon YouTube. */
export function isMusicPlatformLinkedForSalon(
  platform: MusicPlatform,
  connectedPlatforms: MusicPlatform[] | undefined,
  platformLinks: Array<PlatformLinkSummary> | undefined
): boolean {
  if (platform === 'youtube') {
    if (platformLinks?.some((l) => l.platform === 'youtube')) return true;
    return isPlatformConnected(connectedPlatforms, platform);
  }
  if (platformLinks?.length) {
    return isProfilePlatformConnected(platform, platformLinks);
  }
  return isPlatformConnected(connectedPlatforms, platform);
}

/** Salons YouTube : compte YouTube lié requis (hôte et participants). */
export function canAccessYoutubeSalon(
  connectedPlatforms: MusicPlatform[] | undefined,
  platformLinks: Array<PlatformLinkSummary> | undefined
): boolean {
  return isMusicPlatformLinkedForSalon('youtube', connectedPlatforms, platformLinks);
}

/** Auditeur : compte YouTube lié requis pour rejoindre un salon YouTube. L'hôte n'est pas bloqué. */
export function canJoinSalonAsParticipant(
  salonPlatform: MusicPlatform,
  connectedPlatforms: MusicPlatform[] | undefined,
  isHost?: boolean
): boolean {
  if (isHost) return true;
  if (salonPlatform !== 'youtube') return true;
  return isPlatformConnected(connectedPlatforms, salonPlatform);
}

export function salonParticipantAccessMessageKey(
  _platform: MusicPlatform
): 'salon.accessYoutubeRequired' {
  return 'salon.accessYoutubeRequired';
}

export const PLATFORM_LABELS: Record<
  ConnectPlatform,
  { label: string; emoji: string; connectKey: string }
> = {
  youtube: { label: 'YouTube', emoji: '▶️', connectKey: 'platform.connectYoutube' },
  instagram: { label: 'Instagram', emoji: '📸', connectKey: 'platform.connectInstagram' },
};

import { api, ApiRequestError } from './api';
import { getLivesGeo, isFixedMapGeoSource, type LivesGeoPrefs } from './livesGeo';
import type { CreateSalonPlaylistSelection } from '../components/CreateSalonPlaylistPicker';

/** Position initiale du modal création salon (carte / préférences utilisateur). */
export function initialSalonCreateLocation(
  fallbackLatitude: number,
  fallbackLongitude: number
): LivesGeoPrefs {
  const geo = getLivesGeo();
  const useGeoCoords =
    Number.isFinite(geo.latitude) &&
    Number.isFinite(geo.longitude) &&
    (isFixedMapGeoSource(geo.source) || geo.source === 'my_position');
  return {
    ...geo,
    latitude: useGeoCoords ? geo.latitude : fallbackLatitude,
    longitude: useGeoCoords ? geo.longitude : fallbackLongitude,
    label: useGeoCoords ? geo.label : geo.label || 'Carte',
    source: useGeoCoords ? geo.source : geo.source,
  };
}

/** @deprecated Préférer le choix explicite dans CreateSalonModal (SessionLocationPicker). */
export async function resolveSalonCreatePosition(
  fallbackLatitude: number,
  fallbackLongitude: number
): Promise<{ latitude: number; longitude: number }> {
  const geo = getLivesGeo();
  if (isFixedMapGeoSource(geo.source)) {
    return { latitude: geo.latitude, longitude: geo.longitude };
  }
  if (typeof navigator === 'undefined' || !navigator.geolocation) {
    return { latitude: fallbackLatitude, longitude: fallbackLongitude };
  }
  try {
    const pos = await new Promise<GeolocationPosition>((res, rej) =>
      navigator.geolocation.getCurrentPosition(res, rej, {
        enableHighAccuracy: false,
        timeout: 5000,
        maximumAge: 120_000,
      })
    );
    return { latitude: pos.coords.latitude, longitude: pos.coords.longitude };
  } catch {
    return { latitude: fallbackLatitude, longitude: fallbackLongitude };
  }
}

/** Playlists bibliothèque (/me/playlists) : verify-access redondant au submit. */
export function shouldVerifyYoutubePlaylistOnCreate(
  selection: CreateSalonPlaylistSelection | null
): boolean {
  if (!selection) return false;
  return Boolean(selection.playlistUrl?.trim());
}

export function buildPlaylistLoadBody(
  youtubePlaylist: CreateSalonPlaylistSelection | null
): { playlistId?: string; playlistUrl?: string } | null {
  if (!youtubePlaylist) return null;
  if (youtubePlaylist.playlistUrl) return { playlistUrl: youtubePlaylist.playlistUrl };
  if (youtubePlaylist.playlistId) return { playlistId: youtubePlaylist.playlistId };
  return null;
}

export function translateSalonCreateError(
  t: (key: string, options?: Record<string, unknown>) => string,
  e: unknown,
  _platform: 'youtube' = 'youtube'
): string {
  if (e instanceof ApiRequestError) {
    if (e.code === 'SALON_ALREADY_ACTIVE') {
      return t('salon.create.errorAlreadyActive');
    }
    if (e.code === 'HOST_PLATFORM_NOT_LINKED') {
      return t('salon.create.errorPlatformNotLinkedYoutube');
    }
    if (e.message) return e.message;
  }
  if (e instanceof Error && e.message) return e.message;
  return t('salon.create.errorFailed', { defaultValue: 'Impossible de créer le salon.' });
}

/** Charge la playlist après entrée salon (socket `salon_updated`). */
export function deferSalonPlaylistLoad(
  token: string,
  salonId: string,
  body: { playlistId?: string; playlistUrl?: string },
  onError?: (error: unknown) => void
): void {
  void api.salonLoadPlaylist(token, salonId, body).catch((error) => {
    console.warn('[create-salon] deferred playlist load failed', error);
    onError?.(error);
  });
}

