      if (isEvent && saveEventLocation && eventLocation.trim()) {
        writeSavedEventLocation(eventLocation);
      }
      setPosts((prev) => [r.post, ...prev]);
      dispatchMapEventsRefresh();
      setDraft('');
      setImageUrl('');
      setVideoUrl('');
      setIsEvent(false);
      resetEventForm();
