import { useCallback, useEffect, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../context/AuthContext';
import { api } from '../lib/api';
import type { SyslogLine } from '../types';

type ServerLogType = 'pm2' | 'system';
type LineCount = 50 | 100 | 200 | 500;
type LevelFilter = 'all' | 'error' | 'warn' | 'info';

function levelTextColor(level: SyslogLine['level']): string {
  if (level === 'error') return 'text-red-400';
  if (level === 'warn') return 'text-yellow-400';
  return 'text-gray-400';
}

function formatTs(iso: string, locale: string): string {
  try {
    return new Date(iso).toLocaleString(locale, {
      day: '2-digit',
      month: 'short',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    });
  } catch {
    return iso;
  }
}

export function AdminServerLogsPanel({ defaultType = 'pm2' }: { defaultType?: ServerLogType }) {
  const { token } = useAuth();
  const { t, i18n } = useTranslation();
  const [logType, setLogType] = useState<ServerLogType>(defaultType);
  const [lines, setLines] = useState<SyslogLine[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [lineCount, setLineCount] = useState<LineCount>(100);
  const [levelFilter, setLevelFilter] = useState<LevelFilter>('all');
  const [search, setSearch] = useState('');
  const [autoRefresh, setAutoRefresh] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const load = useCallback(async () => {
    if (!token) return;
    setLoading(true);
    try {
      const res = await api.getVpsSyslog(token, { lines: lineCount, type: logType });
      setLines(res.lines);
      setError(null);
      setTimeout(() => {
        if (scrollRef.current) scrollRef.current.scrollTop = 0;
      }, 30);
    } catch (e) {
      setError(e instanceof Error ? e.message : t('admin.support.diag.serverLogsLoadError'));
    } finally {
      setLoading(false);
    }
  }, [token, lineCount, logType, t]);

  useEffect(() => {
    void load();
  }, [load]);

  useEffect(() => {
    if (autoRefresh) {
      intervalRef.current = setInterval(() => void load(), 15_000);
    } else if (intervalRef.current) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
    }
    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  }, [autoRefresh, load]);

  const filtered = lines.filter((l) => {
    if (levelFilter !== 'all' && l.level !== levelFilter) return false;
    if (!search.trim()) return true;
    const q = search.toLowerCase();
    return l.message.toLowerCase().includes(q) || l.source.toLowerCase().includes(q);
  });

  function handleCopy() {
    const text = filtered
      .map((l) => `[${l.ts}] [${l.level.toUpperCase()}] [${l.source}] ${l.message}`)
      .join('\n');
    void navigator.clipboard.writeText(text);
  }

  return (
    <div className="space-y-3">
      <p className="text-xs text-gray-500">
        {logType === 'pm2'
          ? t('admin.support.diag.serverLogsPm2Hint')
          : t('admin.support.diag.serverLogsSystemHint')}
      </p>

      <div className="flex flex-wrap gap-2 items-center">
        <SegmentedControl
          options={[
            { value: 'pm2', label: t('admin.support.diag.logTabPm2') },
            { value: 'system', label: t('admin.support.diag.logTabSystem') },
          ]}
          value={logType}
          onChange={(v) => setLogType(v as ServerLogType)}
        />
        <SegmentedControl
          options={[
            { value: '50', label: '50' },
            { value: '100', label: '100' },
            { value: '200', label: '200' },
            { value: '500', label: '500' },
          ]}
          value={String(lineCount)}
          onChange={(v) => setLineCount(Number(v) as LineCount)}
        />
        <SegmentedControl
          options={[
            { value: 'all', label: t('admin.support.logsLevelAll') },
            { value: 'error', label: t('admin.support.logsLevelError'), accent: 'red' },
            { value: 'warn', label: t('admin.support.logsLevelWarn'), accent: 'yellow' },
            { value: 'info', label: t('admin.support.logsLevelInfo') },
          ]}
          value={levelFilter}
          onChange={(v) => setLevelFilter(v as LevelFilter)}
        />
      </div>

      <div className="flex flex-wrap gap-2">
        <input
          type="search"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder={t('admin.support.logsSearchPlaceholder')}
          className="flex-1 min-w-[10rem] bg-[#1a1a26] border border-[#2d2d3d] rounded-xl px-3 py-2 text-white text-xs outline-none focus:border-purple-500/60"
        />
        <button
          type="button"
          onClick={() => void load()}
          disabled={loading}
          className="px-3 py-2 min-h-[44px] text-xs border border-[#2d2d3d] text-gray-400 hover:text-white rounded-xl disabled:opacity-50"
        >
          {loading ? '…' : t('admin.support.logsRefresh')}
        </button>
        <button
          type="button"
          onClick={() => setAutoRefresh((p) => !p)}
          className={`px-3 py-2 min-h-[44px] text-xs border rounded-xl transition-colors ${
            autoRefresh
              ? 'border-purple-500/50 bg-purple-500/10 text-purple-300'
              : 'border-[#2d2d3d] text-gray-500 hover:text-gray-300'
          }`}
        >
          {t('admin.support.logsAutoRefresh')}
        </button>
        <button
          type="button"
          onClick={handleCopy}
          disabled={filtered.length === 0}
          className="px-3 py-2 min-h-[44px] text-xs border border-[#2d2d3d] text-gray-400 hover:text-white rounded-xl disabled:opacity-50"
        >
          {t('admin.support.logsCopy')}
        </button>
      </div>

      {error && <p className="text-sm text-red-400">{error}</p>}

      <div
        ref={scrollRef}
        className="h-[min(55dvh,24rem)] overflow-y-auto overscroll-contain bg-[#07070f] rounded-xl border border-[#191926] p-2.5 font-mono text-[10px] leading-relaxed space-y-0.5"
      >
        {filtered.length === 0 && !loading ? (
          <p className="text-gray-600 text-center py-10">{t('admin.support.logsEmpty')}</p>
        ) : (
          filtered.map((line, idx) => (
            <div key={`${line.ts}-${idx}`} className={`flex gap-2 ${levelTextColor(line.level)}`}>
              <span className="text-gray-600 shrink-0 tabular-nums">{formatTs(line.ts, i18n.language)}</span>
              <span className="text-purple-400/70 shrink-0 max-w-[5rem] truncate">{line.source}</span>
              <span className="break-all min-w-0">{line.message}</span>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

function SegmentedControl({
  options,
  value,
  onChange,
}: {
  options: { value: string; label: string; accent?: 'red' | 'yellow' }[];
  value: string;
  onChange: (v: string) => void;
}) {
  return (
    <div className="flex rounded-lg overflow-hidden border border-[#2a2a3d] text-[10px] max-w-full overflow-x-auto">
      {options.map((opt) => {
        const active = value === opt.value;
        let activeClass = 'bg-[#2d2d3d] text-white';
        if (active && opt.accent === 'red') activeClass = 'bg-red-900/30 text-red-400';
        if (active && opt.accent === 'yellow') activeClass = 'bg-yellow-900/20 text-yellow-400';
        return (
          <button
            key={opt.value}
            type="button"
            onClick={() => onChange(opt.value)}
            className={`px-2.5 py-1.5 min-h-[44px] sm:min-h-0 whitespace-nowrap transition-colors ${
              active ? activeClass : 'text-gray-500 hover:text-gray-300'
            }`}
          >
            {opt.label}
          </button>
        );
      })}
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';

import { useTranslation } from 'react-i18next';

import { AdminScrollTabBar } from '../components/AdminScrollTabBar';
import { SponsorRegionAutocomplete } from '../components/SponsorRegionAutocomplete';
import { SponsorBannerUploadField } from '../components/SponsorBannerUploadField';

import { useAuth } from '../context/AuthContext';

import { api } from '../lib/api';
import { resolveSponsorLogoSrc } from '../lib/sponsorLogoUpload';

import {

  countsForSponsors,

  defaultPlacementForTab,

  isSponsorActiveAt,

  placementTabToApiPlacement,

  reorderSponsorIdsWithinPlacement,

  SPONSOR_PLACEMENT_TABS,

  type SponsorPlacementTab,

} from '../lib/sponsorAdminPlacement';

import { SPONSOR_IMAGE_SPECS, DEFAULT_DISPLAY_DURATION_SEC, SPONSOR_DISPLAY_DURATION_MAX_SEC, SPONSOR_DISPLAY_DURATION_MIN_SEC } from '../lib/sponsorDisplaySpec';

import { MAP_REGION_MIN_ZOOM } from '../lib/sponsorAds';

import {
  buildSponsorPayloadFromAdminForm,
  computeDisplayDays,
  emptySponsorAdminForm,
  SPONSOR_DISPLAY_DAYS_MAX,
  SPONSOR_DISPLAY_DAYS_MIN,
  sponsorToAdminForm,
  validateSponsorAdminForm,
  type SponsorAdminFormState,
} from '../lib/sponsorAdminForm';

import type { Sponsor, SponsorFilter, SponsorPlacement, SponsorPlatformConfig } from '../types';



const FILTER_OPTIONS: SponsorFilter[] = ['all', 'active', 'inactive'];

const PLACEMENT_OPTIONS: SponsorPlacement[] = ['map_banner', 'feed_inline', 'stories_banner', 'stories_sponsored', 'reels_sponsored'];



function SponsorsSubTabBar({
  subTab,
  onChange,
  t,
}: {
  subTab: SponsorPlacementTab;
  onChange: (tab: SponsorPlacementTab) => void;
  t: (key: string) => string;
}) {
  const labelFor = (tab: SponsorPlacementTab) => {
    if (tab === 'all') return t('admin.sponsors.subTabAll');
    if (tab === 'map_banner') return t('admin.sponsors.subTabMap');
    if (tab === 'feed_inline') return t('admin.sponsors.subTabFeed');
    if (tab === 'stories_banner') return t('admin.sponsors.subTabStories');
    if (tab === 'stories_sponsored') return t('admin.sponsors.subTabStoriesViewer');
    if (tab === 'reels_sponsored') return t('admin.sponsors.subTabReels');
    return t('admin.sponsors.subTabStories');
  };

  return (
    <AdminScrollTabBar
      className="-mx-1 px-1 border-b border-[#1e1e2f]"
      aria-label={t('admin.sponsors.subTabsAria')}
    >
      {SPONSOR_PLACEMENT_TABS.map((tab) => (
        <button
          key={tab}
          type="button"
          onClick={() => onChange(tab)}
          className={`shrink-0 px-2 py-1.5 min-h-8 sm:px-3 sm:py-2 sm:min-h-0 text-[11px] sm:text-xs font-semibold whitespace-nowrap transition border-b-2 -mb-px ${
            subTab === tab
              ? 'border-purple-500 text-white'
              : 'border-transparent text-gray-500 hover:text-gray-300'
          }`}
        >
          {labelFor(tab)}
        </button>
      ))}
    </AdminScrollTabBar>
  );
}

export function AdminSponsorsTab() {
  const { token } = useAuth();
  const { t } = useTranslation();

  const [placementTab, setPlacementTab] = useState<SponsorPlacementTab>('map_banner');

  const [filter, setFilter] = useState<SponsorFilter>('all');

  const [search, setSearch] = useState('');

  const [debouncedSearch, setDebouncedSearch] = useState('');

  const [items, setItems] = useState<Sponsor[]>([]);

  const [counts, setCounts] = useState({ total: 0, active: 0, inactive: 0 });

  const [loading, setLoading] = useState(true);

  const [error, setError] = useState('');

  const [busyId, setBusyId] = useState<string | null>(null);

  const [editingId, setEditingId] = useState<string | null>(null);

  const [showCreate, setShowCreate] = useState(false);

  const [form, setForm] = useState<SponsorAdminFormState>(() => emptySponsorAdminForm('map_banner'));

  const [formError, setFormError] = useState('');

  const [platformConfig, setPlatformConfig] = useState<SponsorPlatformConfig>({
    reelsSponsorEnabled: true,
    reelsSponsorEveryN: 5,
    storiesSponsorEnabled: true,
    storiesSponsorEveryN: 4,
  });

  const [configBusy, setConfigBusy] = useState(false);



  useEffect(() => {

    const tmr = window.setTimeout(() => setDebouncedSearch(search.trim()), 300);

    return () => clearTimeout(tmr);

  }, [search]);



  useEffect(() => {

    setFormError('');

  }, [form]);



  const reload = useCallback(async () => {

    if (!token) return;

    setLoading(true);

    setError('');

    try {

      const res = await api.getAdminSponsors(token, {

        filter,

        placement: placementTabToApiPlacement(placementTab),

        q: debouncedSearch || undefined,

      });

      setItems(res.items);

      setCounts(

        placementTab === 'all' ? res.counts : countsForSponsors(res.items)

      );

    } catch (e) {

      setError(e instanceof Error ? e.message : t('errors.network'));

    } finally {

      setLoading(false);

    }

  }, [token, filter, placementTab, debouncedSearch, t]);



  useEffect(() => {

    void reload();

  }, [reload]);



  useEffect(() => {

    if (!token || (placementTab !== 'reels_sponsored' && placementTab !== 'stories_sponsored')) return;

    api

      .getAdminSponsorsConfig(token)

      .then((r) => setPlatformConfig(r.config))

      .catch(() => undefined);

  }, [token, placementTab]);



  const savePlatformConfig = async (patch: Partial<SponsorPlatformConfig>) => {

    if (!token) return;

    setConfigBusy(true);

    try {

      const res = await api.patchAdminSponsorsConfig(token, patch);

      setPlatformConfig(res.config);

    } catch (e) {

      alert(e instanceof Error ? e.message : t('admin.sponsors.actionError'));

    } finally {

      setConfigBusy(false);

    }

  };



  const handlePlacementTabChange = (tab: SponsorPlacementTab) => {

    setPlacementTab(tab);

    setEditingId(null);

    if (showCreate) {

      setForm((f) => ({ ...f, placement: defaultPlacementForTab(tab) }));

    }

  };



  const openCreateForm = () => {

    setShowCreate((v) => {

      const next = !v;

      if (next) {

        setEditingId(null);

        setFormError('');

        setForm(emptySponsorAdminForm(defaultPlacementForTab(placementTab)));
      }

      return next;

    });

  };



  const handleCreate = async () => {

    if (!token) {

      setFormError(t('errors.sessionExpired'));

      return;

    }

    const validationError = validateSponsorAdminForm(form, t);

    if (validationError) {

      setFormError(validationError);

      return;

    }

    setFormError('');

    setBusyId('create');

    try {

      await api.createAdminSponsor(token, buildSponsorPayloadFromAdminForm(form));

      setForm(emptySponsorAdminForm(defaultPlacementForTab(placementTab)));

      setShowCreate(false);

      await reload();

    } catch (e) {

      setFormError(e instanceof Error ? e.message : t('admin.sponsors.actionError'));

    } finally {

      setBusyId(null);

    }

  };



  const handleSave = async (id: string) => {

    if (!token) {

      setFormError(t('errors.sessionExpired'));

      return;

    }

    const validationError = validateSponsorAdminForm(form, t);

    if (validationError) {

      setFormError(validationError);

      return;

    }

    setFormError('');

    setBusyId(id);

    try {

      await api.updateAdminSponsor(token, id, buildSponsorPayloadFromAdminForm(form));

      setEditingId(null);

      await reload();

    } catch (e) {

      setFormError(e instanceof Error ? e.message : t('admin.sponsors.actionError'));

    } finally {

      setBusyId(null);

    }

  };



  const handleToggle = async (id: string) => {

    if (!token) return;

    setBusyId(id);

    try {

      await api.toggleAdminSponsor(token, id);

      await reload();

    } catch (e) {

      alert(e instanceof Error ? e.message : t('admin.sponsors.actionError'));

    } finally {

      setBusyId(null);

    }

  };



  const handleDelete = async (id: string) => {

    if (!token) return;

    if (!window.confirm(t('admin.sponsors.deleteConfirm'))) return;

    setBusyId(id);

    try {

      await api.deleteAdminSponsor(token, id);

      if (editingId === id) setEditingId(null);

      await reload();

    } catch (e) {

      alert(e instanceof Error ? e.message : t('admin.sponsors.actionError'));

    } finally {

      setBusyId(null);

    }

  };



  const moveSponsor = async (id: string, direction: 'up' | 'down') => {

    if (!token) return;

    const idx = items.findIndex((s) => s.id === id);

    if (idx < 0) return;

    const swapIdx = direction === 'up' ? idx - 1 : idx + 1;

    if (swapIdx < 0 || swapIdx >= items.length) return;



    setBusyId(id);

    try {

      let ids: string[];

      if (placementTab === 'all') {

        ids = items.map((s) => s.id);

        [ids[idx], ids[swapIdx]] = [ids[swapIdx], ids[idx]];

      } else {

        const allRes = await api.getAdminSponsors(token, {

          filter,

          q: debouncedSearch || undefined,

        });

        const reordered = reorderSponsorIdsWithinPlacement(

          allRes.items,

          placementTab,

          id,

          direction

        );

        if (!reordered) return;

        ids = reordered;

      }

      const res = await api.reorderAdminSponsors(token, ids);

      setItems(

        placementTab === 'all'

          ? res.items

          : res.items.filter((s) => s.placement === placementTab)

      );

    } catch (e) {

      alert(e instanceof Error ? e.message : t('admin.sponsors.actionError'));

    } finally {

      setBusyId(null);

    }

  };



  const placementLabel = (placement: SponsorPlacement) => t(`admin.sponsors.placement.${placement}`);

  const filterLabel = (f: SponsorFilter) => {

    if (f === 'active') return t('admin.sponsors.filterActive');

    if (f === 'inactive') return t('admin.sponsors.filterInactive');

    return t('admin.sponsors.filterAll');

  };



  const imageSpec = SPONSOR_IMAGE_SPECS[form.placement];

  const renderFormFields = (
    formId: string,
    opts: { mode: 'create' } | { mode: 'edit'; editId: string }
  ) => {
    const isSubmitBusy =
      opts.mode === 'create' ? busyId === 'create' : busyId === opts.editId;
    const showMapBanner = form.placement === 'map_banner';
    const showStoriesBanner = form.placement === 'stories_banner';

    return (
      <form
        id={formId}
        noValidate
        onSubmit={(e) => {
          e.preventDefault();
          if (opts.mode === 'create') void handleCreate();
          else void handleSave(opts.editId);
        }}
        className="space-y-4"
      >
        {formError ? (
          <p
            role="alert"
            className="text-red-400 text-sm bg-red-500/10 border border-red-500/30 rounded-xl px-3 py-2"
          >
            {formError}
          </p>
        ) : null}

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          <label className="block text-xs text-gray-400">
            {t('admin.sponsors.fieldName')}
            <input
