import { useCallback, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../context/AuthContext';
import { api } from '../lib/api';
import { AdminCostsTab } from './AdminCostsTab';
import { AdminDonationsTab } from './AdminDonationsTab';
import { AnalyticsVpsTab } from './AnalyticsVpsTab';

export type AnalyticsPeriod = 'day' | 'week' | 'month' | 'year';
export type AnalyticsSubTab = 'overview' | 'vps' | 'costs' | 'donations';

type AnalyticsSummary = Awaited<ReturnType<typeof api.getAnalyticsSummary>>;

const PERIOD_OPTIONS: AnalyticsPeriod[] = ['day', 'week', 'month', 'year'];

function periodTotalLabel(period: AnalyticsPeriod, t: (key: string) => string): string {
  if (period === 'day') return t('admin.analytics.periodTotalDay');
  if (period === 'week') return t('admin.analytics.periodTotalWeek');
  if (period === 'month') return t('admin.analytics.periodTotalMonth');
  return t('admin.analytics.periodTotalYear');
}

function periodLabel(period: AnalyticsPeriod, t: (key: string) => string): string {
  if (period === 'day') return t('admin.analytics.periodDay');
  if (period === 'week') return t('admin.analytics.periodWeek');
  if (period === 'month') return t('admin.analytics.periodMonth');
  return t('admin.analytics.periodYear');
}

function StatCard({
  label,
  value,
  sub,
  color = 'purple',
}: {
  label: string;
  value: number | string;
  sub?: string;
  color?: 'purple' | 'green' | 'blue' | 'red' | 'yellow';
}) {
  const colorMap = {
    purple: 'from-purple-600/20 to-purple-900/10 border-purple-500/20 text-purple-300',
    green: 'from-green-600/20 to-green-900/10 border-green-500/20 text-green-300',
    blue: 'from-blue-600/20 to-blue-900/10 border-blue-500/20 text-blue-300',
    red: 'from-red-600/20 to-red-900/10 border-red-500/20 text-red-300',
    yellow: 'from-yellow-600/20 to-yellow-900/10 border-yellow-500/20 text-yellow-300',
  };
  return (
    <div className={`bg-gradient-to-br ${colorMap[color]} border rounded-2xl p-4`}>
      <p className="text-[11px] font-semibold text-gray-400 uppercase tracking-wider mb-1">{label}</p>
      <p className={`text-3xl font-bold ${colorMap[color].split(' ')[3]}`}>{value}</p>
      {sub && <p className="text-xs text-gray-500 mt-0.5">{sub}</p>}
    </div>
  );
}

function BarChart({
  labels,
  values,
  color = '#9b7bd4',
  height = 80,
}: {
  labels: string[];
  values: number[];
  color?: string;
  height?: number;
}) {
  const max = Math.max(...values, 1);
  return (
    <div className="flex items-end gap-1.5" style={{ height }}>
      {values.map((v, i) => {
        const pct = (v / max) * 100;
        return (
          <div key={i} className="flex-1 flex flex-col items-center gap-1 min-w-0">
            <span
              className="text-[9px] text-gray-500 font-mono"
              style={{ visibility: v > 0 ? 'visible' : 'hidden' }}
            >
              {v}
            </span>
            <div
              className="w-full rounded-t-sm transition-all"
              style={{
                height: v === 0 ? '0%' : `${Math.max(pct, 2)}%`,
                backgroundColor: color,
                opacity: v === 0 ? 0 : 0.85,
              }}
            />
            <span className="text-[8px] text-gray-600 truncate w-full text-center">{labels[i]}</span>
          </div>
        );
      })}
    </div>
  );
}

function ChartCard({
  title,
  labels,
  values,
  color,
  periodTotal,
  emptyLabel,
}: {
  title: string;
  labels: string[];
  values: number[];
  color?: string;
  periodTotal: string;
  emptyLabel: string;
}) {
  const total = values.reduce((a, b) => a + b, 0);
  return (
    <div className="bg-[#0f0f17] border border-[#1e1e2f] rounded-2xl p-4">
      <div className="flex items-baseline justify-between mb-3">
        <p className="text-sm font-semibold text-white">{title}</p>
        <span className="text-xs text-gray-500">
          {total} {periodTotal}
        </span>
      </div>
      {values.some((v) => v > 0) ? (
        <BarChart labels={labels} values={values} color={color} height={72} />
      ) : (
        <p className="text-xs text-gray-600 py-6 text-center">{emptyLabel}</p>
      )}
    </div>
  );
}

function AnalyticsSubTabBar({
  subTab,
  onChange,
  t,
}: {
  subTab: AnalyticsSubTab;
  onChange: (tab: AnalyticsSubTab) => void;
  t: (key: string) => string;
}) {
  const items: { id: AnalyticsSubTab; label: string }[] = [
    { id: 'overview', label: t('admin.analytics.subTabOverview') },
    { id: 'vps', label: t('admin.analytics.subTabVps') },
    { id: 'costs', label: t('admin.analytics.subTabCosts') },
    { id: 'donations', label: t('admin.analytics.subTabDonations') },
  ];

  return (
    <nav
      className="flex gap-1 overflow-x-auto pb-0.5 border-b border-[#1e1e2f]"
      aria-label={t('admin.analytics.subTabsAria')}
    >
      {items.map((item) => (
        <button
          key={item.id}
          type="button"
          onClick={() => onChange(item.id)}
          className={`px-3 py-2 text-xs font-semibold whitespace-nowrap transition border-b-2 -mb-px ${
            subTab === item.id
              ? 'border-purple-500 text-white'
              : 'border-transparent text-gray-500 hover:text-gray-300'
          }`}
        >
          {item.label}
        </button>
      ))}
    </nav>
  );
}

export function AnalyticsPage({
  onBack,
  embedded = false,
  initialSubTab = 'overview',
}: {
  onBack?: () => void;
  embedded?: boolean;
  initialSubTab?: AnalyticsSubTab;
}) {
  const { token } = useAuth();
  const { t, i18n } = useTranslation();
  const [subTab, setSubTab] = useState<AnalyticsSubTab>(initialSubTab);
  const [period, setPeriod] = useState<AnalyticsPeriod>('week');
  const [summary, setSummary] = useState<AnalyticsSummary | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(() => {
    if (!token) return;
    setLoading(true);
    api
      .getAnalyticsSummary(token, { period, locale: i18n.language })
      .then((r) => {
        setSummary(r);
        setError(null);
      })
      .catch((e) => setError(e instanceof Error ? e.message : t('admin.analytics.error')))
      .finally(() => setLoading(false));
  }, [token, period, i18n.language, t]);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    setSubTab(initialSubTab);
  }, [initialSubTab]);

  const periodTotal = periodTotalLabel(period, t);

  return (
    <div className={`flex flex-col ${embedded ? '' : 'h-full min-h-0'} bg-[#0b0b0f]`}>
      {!embedded && (
        <header className="shrink-0 flex items-center gap-3 p-4 border-b border-[#1e1e2f] bg-[#0e0e14]">
          {onBack && (
            <button
              type="button"
              onClick={onBack}
              className="text-gray-400 hover:text-white text-xl shrink-0"
            >
              ←
            </button>
          )}
          <div className="flex-1 min-w-0">
            <h1 className="text-lg font-bold text-white">{t('admin.analytics.title')}</h1>
            <p className="text-xs text-gray-500">{t('admin.analytics.subtitle')}</p>
          </div>
          <button
            type="button"
            onClick={load}
            disabled={loading}
            className="px-3 py-1.5 text-xs border border-[#2d2d3d] text-gray-400 hover:text-white rounded-full disabled:opacity-50"
          >
            {loading ? '...' : t('admin.analytics.refresh')}
          </button>
        </header>
      )}

      {embedded && (
        <div className="flex items-center justify-between mb-4">
          <p className="text-xs text-gray-500">{t('admin.analytics.subtitle')}</p>
          <button
            type="button"
            onClick={load}
            disabled={loading}
            className="px-3 py-1.5 text-xs border border-[#2d2d3d] text-gray-400 hover:text-white rounded-full disabled:opacity-50"
          >
            {loading ? '...' : '↻'}
          </button>
        </div>
      )}

      <div className={`${embedded ? '' : 'flex-1 min-h-0 overflow-y-auto'} p-4 space-y-6`}>
        <AnalyticsSubTabBar subTab={subTab} onChange={setSubTab} t={t} />

        {subTab === 'vps' && <AnalyticsVpsTab />}

        {subTab === 'costs' && <AdminCostsTab />}

        {subTab === 'donations' && <AdminDonationsTab />}

        {subTab === 'overview' && (
          <>
        <div>
          <p className="text-[11px] font-semibold text-gray-500 uppercase tracking-wider mb-2">
            {t('admin.analytics.periodLabel')}
          </p>
          <div
            className="flex gap-1 overflow-x-auto"
            role="group"
            aria-label={t('admin.analytics.periodLabel')}
          >
            {PERIOD_OPTIONS.map((option) => (
              <button
                key={option}
                type="button"
                onClick={() => setPeriod(option)}
                className={`px-3 py-1.5 rounded-full text-xs font-semibold whitespace-nowrap transition ${
                  period === option
                    ? 'bg-purple-600 text-white'
                    : 'bg-[#1a1a26] text-gray-400 hover:text-white'
                }`}
              >
                {periodLabel(option, t)}
              </button>
            ))}
          </div>
        </div>

        {error && (
          <div className="bg-red-900/20 border border-red-500/30 rounded-xl px-4 py-3 text-sm text-red-300">
            {error}
          </div>
        )}

        {loading && !summary && (
          <div className="flex items-center justify-center py-20">
            <p className="text-gray-500 text-sm">{t('admin.analytics.loading')}</p>
          </div>
        )}

        {summary && (
          <>
            <section>
              <h2 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">
                {t('admin.analytics.snapshotTitle')}
              </h2>
              <div className="grid grid-cols-2 gap-3">
                <StatCard
                  label={t('admin.analytics.totalUsers')}
                  value={summary.snapshot.totalUsers}
                  color="purple"
                />
                <StatCard
                  label={t('admin.analytics.dau24h')}
                  value={summary.snapshot.dau24h}
                  sub={t('admin.analytics.dau30d', { count: summary.snapshot.dau30d })}
                  color="green"
                />
                <StatCard
                  label={t('admin.analytics.newUsersToday')}
                  value={summary.snapshot.newUsersToday}
                  color="blue"
                />
                <StatCard
                  label={t('admin.analytics.activeSalons')}
                  value={summary.snapshot.activeSalons}
                  sub={t('admin.analytics.activeLives', { count: summary.snapshot.activeLives })}
                  color="red"
                />
                <StatCard
                  label={t('admin.analytics.totalMessages')}
                  value={summary.snapshot.totalMessages}
                  color="yellow"
                />
                <StatCard
                  label={t('admin.analytics.totalMatches')}
                  value={summary.snapshot.totalMatches}
                  color="purple"
                />
                <StatCard
                  label={t('admin.analytics.totalReels')}
                  value={summary.snapshot.totalReels}
                  color="blue"
                />
                <StatCard
                  label={t('admin.analytics.totalFeedPosts')}
                  value={summary.snapshot.totalFeedPosts}
                  color="green"
                />
              </div>
            </section>

            <section>
              <h2 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">
                {t('admin.analytics.activityTitle', { period: periodLabel(period, t) })}
              </h2>
              <div className="grid grid-cols-1 gap-3">
                <ChartCard
                  title={t('admin.analytics.chartLogins')}
                  labels={summary.series.labels}
                  values={summary.series.logins}
                  color="#9b7bd4"
                  periodTotal={periodTotal}
                  emptyLabel={t('admin.analytics.noActivity')}
                />
                <ChartCard
                  title={t('admin.analytics.chartMessages')}
                  labels={summary.series.labels}
                  values={summary.series.messagesSent}
                  color="#f59e0b"
                  periodTotal={periodTotal}
                  emptyLabel={t('admin.analytics.noActivity')}
                />
                <ChartCard
                  title={t('admin.analytics.chartMatches')}
                  labels={summary.series.labels}
                  values={summary.series.matchesCreated}
                  color="#ec4899"
                  periodTotal={periodTotal}
                  emptyLabel={t('admin.analytics.noActivity')}
                />
                <ChartCard
                  title={t('admin.analytics.chartSalons')}
                  labels={summary.series.labels}
                  values={summary.series.salonsCreated}
                  color="#6366f1"
                  periodTotal={periodTotal}
                  emptyLabel={t('admin.analytics.noActivity')}
                />
                <ChartCard
                  title={t('admin.analytics.chartLives')}
                  labels={summary.series.labels}
                  values={summary.series.livesStarted}
                  color="#ef4444"
                  periodTotal={periodTotal}
                  emptyLabel={t('admin.analytics.noActivity')}
                />
                <ChartCard
                  title={t('admin.analytics.chartReels')}
                  labels={summary.series.labels}
                  values={summary.series.reelsViewed}
                  color="#22c55e"
                  periodTotal={periodTotal}
                  emptyLabel={t('admin.analytics.noActivity')}
                />
                <ChartCard
                  title={t('admin.analytics.chartFavorites')}
                  labels={summary.series.labels}
                  values={summary.series.favoritesAdded}
                  color="#f97316"
                  periodTotal={periodTotal}
                  emptyLabel={t('admin.analytics.noActivity')}
                />
              </div>
            </section>

            <p className="text-center text-[10px] text-gray-700 pb-4">
              {t('admin.analytics.dataNote')}
            </p>
          </>
        )}
          </>
        )}
      </div>
    </div>
  );
}

import { useCallback, useEffect, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../context/AuthContext';
import { api } from '../lib/api';
import type { SyslogLine, SyslogResponse } from '../types';

type LogType = 'pm2' | 'system';
type LineCount = 50 | 100 | 200;
type LevelFilter = 'all' | 'error' | 'warn' | 'info';

function levelTextColor(level: SyslogLine['level']): string {
  if (level === 'error') return 'text-red-400';
  if (level === 'warn') return 'text-yellow-400';
  return 'text-gray-400';
}

function levelBadgeClass(level: SyslogLine['level']): string {
  if (level === 'error') return 'text-red-500 bg-red-500/10';
  if (level === 'warn') return 'text-yellow-500 bg-yellow-500/10';
  return 'text-gray-600 bg-gray-500/10';
}

function levelBadgeLabel(level: SyslogLine['level']): string {
  if (level === 'error') return 'ERR';
  if (level === 'warn') return 'WRN';
  return 'INF';
}

function formatTs(iso: string): string {
  try {
    const d = new Date(iso);
    return d.toLocaleTimeString('fr-FR', {
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    });
  } catch {
    return iso.slice(11, 19);
  }
}

export function AnalyticsSyslogSection() {
  const { token } = useAuth();
  const { t } = useTranslation();
  const [data, setData] = useState<SyslogResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [logType, setLogType] = useState<LogType>('pm2');
  const [lineCount, setLineCount] = useState<LineCount>(100);
  const [levelFilter, setLevelFilter] = useState<LevelFilter>('all');
  const [autoRefresh, setAutoRefresh] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const load = useCallback(() => {
    if (!token) return;
    setLoading(true);
    api
      .getVpsSyslog(token, { lines: lineCount, type: logType })
      .then((r) => {
        setData(r);
        setError(null);
        // Scroll to bottom after render
        setTimeout(() => {
          if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
          }
        }, 30);
      })
      .catch((e) =>
        setError(e instanceof Error ? e.message : t('admin.analytics.syslogError')),
      )
      .finally(() => setLoading(false));
  }, [token, lineCount, logType, t]);

  // Reload when params change
  useEffect(() => {
    load();
  }, [load]);

  // Auto-refresh every 10 s
  useEffect(() => {
    if (autoRefresh) {
      intervalRef.current = setInterval(load, 10_000);
    } else {
      if (intervalRef.current !== null) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
    }
    return () => {
      if (intervalRef.current !== null) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
    };
  }, [autoRefresh, load]);

  const filteredLines: SyslogLine[] =
    data?.lines.filter((l) => levelFilter === 'all' || l.level === levelFilter) ?? [];

  function handleCopy() {
    const text = filteredLines
      .map((l) => `[${l.ts}] [${l.level.toUpperCase()}] ${l.message}`)
      .join('\n');
    void navigator.clipboard.writeText(text);
  }

  function handleDownload() {
    const text = filteredLines
      .map((l) => `[${l.ts}] [${l.level.toUpperCase()}] [${l.source}] ${l.message}`)
      .join('\n');
    const blob = new Blob([text], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `syslog-${logType}-${new Date().toISOString().slice(0, 19).replace(/:/g, '-')}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  }

  return (
    <section className="bg-[#0f0f17] border border-[#1e1e2f] rounded-2xl p-4 space-y-3">
      {/* ── Row 1 : title + type/count/level selectors ── */}
      <div className="flex items-center justify-between gap-2 flex-wrap">
        <h2 className="text-sm font-semibold text-white">
          {t('admin.analytics.syslogTitle')}
        </h2>
        <div className="flex items-center gap-1.5 flex-wrap justify-end">
          {/* Log type */}
          <SegmentedControl
            options={[
              { value: 'pm2', label: 'PM2' },
              { value: 'system', label: t('admin.analytics.syslogTypeSystem') },
            ]}
            value={logType}
            onChange={(v) => setLogType(v as LogType)}
          />
          {/* Line count */}
          <SegmentedControl
            options={[
              { value: '50', label: '50' },
              { value: '100', label: '100' },
              { value: '200', label: '200' },
            ]}
            value={String(lineCount)}
            onChange={(v) => setLineCount(Number(v) as LineCount)}
          />
          {/* Level filter */}
          <SegmentedControl
            options={[
              { value: 'all', label: t('admin.analytics.syslogLevelAll') },
              { value: 'error', label: t('admin.analytics.syslogLevelError'), accent: 'red' },
              { value: 'warn', label: t('admin.analytics.syslogLevelWarn'), accent: 'yellow' },
              { value: 'info', label: t('admin.analytics.syslogLevelInfo') },
            ]}
            value={levelFilter}
            onChange={(v) => setLevelFilter(v as LevelFilter)}
          />
        </div>
      </div>

      {/* ── Row 2 : auto-refresh + actions ── */}
      <div className="flex items-center justify-between gap-2">
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={() => setAutoRefresh((prev) => !prev)}
            className={`flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] border transition-colors ${
              autoRefresh
                ? 'border-purple-500/50 bg-purple-500/10 text-purple-300'
                : 'border-[#2d2d3d] text-gray-500 hover:text-gray-300'
            }`}
          >
            <span
              className={`inline-block w-1.5 h-1.5 rounded-full shrink-0 ${
                autoRefresh ? 'bg-purple-400 animate-pulse' : 'bg-gray-600'
              }`}
            />
            {t('admin.analytics.syslogAutoRefresh')}
          </button>
          <button
            type="button"
            onClick={load}
            disabled={loading}
            className="px-2.5 py-1 text-[10px] border border-[#2d2d3d] text-gray-400 hover:text-white rounded-full disabled:opacity-50 transition-colors"
          >
            {loading ? '…' : '↻'}
          </button>
        </div>
        <div className="flex items-center gap-1.5">
          <button
            type="button"
            onClick={handleCopy}
            disabled={filteredLines.length === 0}
            className="px-2.5 py-1 text-[10px] border border-[#2d2d3d] text-gray-400 hover:text-white rounded-full disabled:opacity-50 transition-colors"
          >
            {t('admin.analytics.syslogCopy')}
          </button>
          <button
            type="button"
            onClick={handleDownload}
            disabled={filteredLines.length === 0}
            className="px-2.5 py-1 text-[10px] border border-[#2d2d3d] text-gray-400 hover:text-white rounded-full disabled:opacity-50 transition-colors"
          >
            ↓ {t('admin.analytics.syslogDownload')}
          </button>
        </div>
      </div>

      {/* ── Error banner ── */}
      {error && (
        <div className="bg-red-900/20 border border-red-500/30 rounded-xl px-3 py-2 text-xs text-red-300">
          {error}
        </div>
      )}

      {/* ── Log viewer ── */}
      <div
        ref={scrollRef}
        className="h-96 overflow-y-auto bg-[#07070f] rounded-xl border border-[#191926] p-2.5 font-mono text-[10px] leading-relaxed space-y-px"
      >
        {filteredLines.length === 0 && !loading ? (
          <p className="text-gray-600 text-center py-10">
            {t('admin.analytics.syslogEmpty')}
          </p>
        ) : (
          filteredLines.map((line, i) => (
            <div
              key={i}
              className={`flex gap-2 px-1 py-px rounded hover:bg-white/[0.025] ${levelTextColor(line.level)}`}
            >
              {/* Timestamp */}
              <span className="text-gray-600 shrink-0 tabular-nums select-none">
                {formatTs(line.ts)}
              </span>
              {/* Level badge */}
              <span
                className={`shrink-0 font-bold px-1 rounded text-[9px] self-start mt-px ${levelBadgeClass(line.level)}`}
              >
                {levelBadgeLabel(line.level)}
              </span>
              {/* Source (system only) */}
              {logType === 'system' && (
                <span className="text-purple-400/60 shrink-0 max-w-[90px] truncate self-start">
                  {line.source}
                </span>
              )}
              {/* Message */}
              <span className="break-all min-w-0">{line.message}</span>
            </div>
          ))
        )}
      </div>

      {/* ── Footer: line count + fetch time ── */}
      {data && (
        <p className="text-[10px] text-gray-600">
          {t('admin.analytics.syslogFetched', {
            count: filteredLines.length,
            total: data.count,
          })}
          {' · '}
          {new Date(data.fetchedAt).toLocaleTimeString()}
        </p>
      )}
    </section>
  );
}

/* ─── Reusable segmented-control pill ─────────────────────────── */
interface SegOption {
  value: string;
  label: string;
  accent?: 'red' | 'yellow';
}

function SegmentedControl({
  options,
  value,
  onChange,
}: {
  options: SegOption[];
  value: string;
  onChange: (v: string) => void;
}) {
  return (
    <div className="flex rounded-lg overflow-hidden border border-[#2a2a3d] text-[10px]">
      {options.map((opt) => {
        const active = value === opt.value;
        let activeClass = 'bg-[#2d2d3d] text-white';
        if (active && opt.accent === 'red') activeClass = 'bg-red-900/30 text-red-400';
        if (active && opt.accent === 'yellow') activeClass = 'bg-yellow-900/20 text-yellow-400';
        return (
          <button
            key={opt.value}
            type="button"
            onClick={() => onChange(opt.value)}
            className={`px-2.5 py-1 transition-colors ${
              active ? activeClass : 'text-gray-500 hover:text-gray-300'
            }`}
          >
            {opt.label}
          </button>
        );
      })}
    </div>
  );
}

