import { useCallback, useEffect, useState, type ReactNode } from 'react';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../context/AuthContext';
import { api } from '../lib/api';
import type { VpsMetricsReport } from '../types';
import { AnalyticsSyslogSection } from './AnalyticsSyslogSection';

function formatBytes(bytes: number, locale: string): string {
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let value = bytes;
  let unitIndex = 0;
  while (value >= 1024 && unitIndex < units.length - 1) {
    value /= 1024;
    unitIndex += 1;
  }
  return `${value.toLocaleString(locale, { maximumFractionDigits: 1 })} ${units[unitIndex]}`;
}

function formatUptime(seconds: number, locale: string): string {
  const days = Math.floor(seconds / 86400);
  const hours = Math.floor((seconds % 86400) / 3600);
  const mins = Math.floor((seconds % 3600) / 60);
  if (days > 0) {
    return `${days}j ${hours}h`;
  }
  if (hours > 0) {
    return `${hours}h ${mins}min`;
  }
  return `${mins.toLocaleString(locale)} min`;
}

function formatDateTime(iso: string, locale: string): string {
  return new Date(iso).toLocaleString(locale, {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  });
}

function SectionCard({ title, children }: { title: string; children: ReactNode }) {
  return (
    <section className="bg-[#0f0f17] border border-[#1e1e2f] rounded-2xl p-4 space-y-3">
      <h2 className="text-sm font-semibold text-white">{title}</h2>
      {children}
    </section>
  );
}

function UsageBar({ percent, color = '#9b7bd4' }: { percent: number; color?: string }) {
  const clamped = Math.min(100, Math.max(0, percent));
  const barColor =
    clamped >= 90 ? '#ef4444' : clamped >= 75 ? '#f59e0b' : color;
  return (
    <div className="h-2 bg-[#1a1a26] rounded-full overflow-hidden">
      <div
        className="h-full rounded-full transition-all"
        style={{ width: `${clamped}%`, backgroundColor: barColor }}
      />
    </div>
  );
}

function MetricRow({ label, value, sub }: { label: string; value: string; sub?: string }) {
  return (
    <div className="flex items-start justify-between gap-3 text-sm">
      <span className="text-gray-500 shrink-0">{label}</span>
      <div className="text-right min-w-0">
        <span className="text-gray-200 font-medium">{value}</span>
        {sub && <p className="text-[10px] text-gray-600 mt-0.5">{sub}</p>}
      </div>
    </div>
  );
}

function sourceLabel(source: VpsMetricsReport['source'], t: (key: string) => string): string {
  if (source === 'mock') return t('admin.analytics.vpsSourceMock');
  if (source === 'partial') return t('admin.analytics.vpsSourcePartial');
  return t('admin.analytics.vpsSourceSystem');
}

export function AnalyticsVpsTab() {
  const { token } = useAuth();
  const { t, i18n } = useTranslation();
  const [metrics, setMetrics] = useState<VpsMetricsReport | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const locale = i18n.language.startsWith('en') ? 'en-GB' : 'fr-FR';

  const load = useCallback(() => {
    if (!token) return;
    setLoading(true);
    api
      .getVpsMetrics(token)
      .then((r) => {
        setMetrics(r);
        setError(null);
      })
      .catch((e) => setError(e instanceof Error ? e.message : t('admin.analytics.vpsError')))
      .finally(() => setLoading(false));
  }, [token, t]);

  useEffect(() => {
    load();
  }, [load]);

  if (loading && !metrics) {
    return (
      <div className="flex items-center justify-center py-16">
        <p className="text-gray-500 text-sm">{t('admin.analytics.vpsLoading')}</p>
      </div>
    );
  }

  return (
    <div className="space-y-4 pb-4">
      <div className="flex items-center justify-between gap-2">
        <p className="text-xs text-gray-500">{t('admin.analytics.vpsSubtitle')}</p>
        <button
          type="button"
          onClick={load}
          disabled={loading}
          className="px-3 py-1.5 text-xs border border-[#2d2d3d] text-gray-400 hover:text-white rounded-full disabled:opacity-50 shrink-0"
        >
          {loading ? '...' : t('admin.analytics.refresh')}
        </button>
      </div>

      {metrics?.fetchedAt && (
        <p className="text-[10px] text-gray-600">
          {t('admin.analytics.vpsLastUpdated', {
            date: formatDateTime(metrics.fetchedAt, locale),
          })}
        </p>
      )}

      {error && (
        <div className="bg-red-900/20 border border-red-500/30 rounded-xl px-4 py-3 text-sm text-red-300">
          {error}
        </div>
      )}

      {metrics && (
        <>
          <SectionCard title={t('admin.analytics.vpsHostTitle')}>
            <div className="space-y-2">
              <MetricRow label={t('admin.analytics.vpsHostname')} value={metrics.hostname} />
              <MetricRow label={t('admin.analytics.vpsPlatform')} value={metrics.platform} />
              <MetricRow label={t('admin.analytics.vpsEnv')} value={metrics.env} />
              <MetricRow
                label={t('admin.analytics.vpsUptime')}
                value={formatUptime(metrics.uptimeSeconds, locale)}
              />
              <MetricRow
                label={t('admin.analytics.vpsSource')}
                value={sourceLabel(metrics.source, t)}
              />
            </div>
          </SectionCard>

          <SectionCard title={t('admin.analytics.vpsMemoryTitle')}>
            <div className="space-y-3">
              <div>
                <div className="flex justify-between text-xs mb-1.5">
                  <span className="text-gray-400">
                    {formatBytes(metrics.memory.usedBytes, locale)} /{' '}
                    {formatBytes(metrics.memory.totalBytes, locale)}
                  </span>
                  <span className="text-purple-300 font-semibold">{metrics.memory.usedPercent}%</span>
                </div>
                <UsageBar percent={metrics.memory.usedPercent} />
              </div>
              <MetricRow
                label={t('admin.analytics.vpsMemoryProcess')}
                value={formatBytes(metrics.memory.processRssBytes, locale)}
              />
              <MetricRow
                label={t('admin.analytics.vpsMemoryHeap')}
                value={formatBytes(metrics.memory.processHeapUsedBytes, locale)}
              />
            </div>
          </SectionCard>

          <SectionCard title={t('admin.analytics.vpsDiskTitle')}>
            {metrics.disk.source === 'unavailable' || metrics.disk.usedBytes == null ? (
              <p className="text-sm text-gray-500">{t('admin.analytics.vpsDiskUnavailable')}</p>
            ) : (
              <div className="space-y-3">
                <div>
                  <div className="flex justify-between text-xs mb-1.5">
                    <span className="text-gray-400">
                      {formatBytes(metrics.disk.usedBytes, locale)} /{' '}
                      {formatBytes(metrics.disk.totalBytes!, locale)}
                    </span>
                    <span className="text-purple-300 font-semibold">
                      {metrics.disk.usedPercent}%
                    </span>
                  </div>
                  <UsageBar percent={metrics.disk.usedPercent ?? 0} color="#6366f1" />
                </div>
                <MetricRow
                  label={t('admin.analytics.vpsDiskFree')}
                  value={formatBytes(metrics.disk.freeBytes!, locale)}
                />
                {metrics.disk.mountPoint && (
                  <MetricRow
                    label={t('admin.analytics.vpsDiskMount')}
                    value={metrics.disk.mountPoint}
                  />
                )}
              </div>
            )}
          </SectionCard>

          <SectionCard title={t('admin.analytics.vpsCpuTitle')}>
            <div className="space-y-2">
              <MetricRow
                label={t('admin.analytics.vpsCpuCores')}
                value={String(metrics.cpu.cores)}
              />
              <MetricRow label={t('admin.analytics.vpsCpuModel')} value={metrics.cpu.model} />
              {metrics.cpu.loadAverage1m != null ? (
                <>
                  {metrics.cpu.loadPercent != null && (
                    <div className="pt-1">
                      <div className="flex justify-between text-xs mb-1.5">
                        <span className="text-gray-400">{t('admin.analytics.vpsCpuLoadPercent')}</span>
                        <span className="text-purple-300 font-semibold">
                          {metrics.cpu.loadPercent}%
                        </span>
                      </div>
                      <UsageBar percent={Math.min(metrics.cpu.loadPercent, 100)} color="#22c55e" />
                    </div>
                  )}
                  <MetricRow
                    label={t('admin.analytics.vpsCpuLoad1m')}
                    value={String(metrics.cpu.loadAverage1m)}
                  />
                  <MetricRow
                    label={t('admin.analytics.vpsCpuLoad5m')}
                    value={String(metrics.cpu.loadAverage5m)}
                  />
                  <MetricRow
                    label={t('admin.analytics.vpsCpuLoad15m')}
                    value={String(metrics.cpu.loadAverage15m)}
                  />
                </>
              ) : (
                <p className="text-sm text-gray-500">{t('admin.analytics.vpsCpuUnavailable')}</p>
              )}
            </div>
          </SectionCard>

          <SectionCard title={t('admin.analytics.vpsLatencyTitle')}>
            <MetricRow
              label={t('admin.analytics.vpsLatencyTitle')}
              value={t('admin.analytics.vpsLatencyValue', { ms: metrics.latencyMs })}
              sub={
                metrics.latencySource === 'postgres'
                  ? t('admin.analytics.vpsLatencyPostgres')
                  : t('admin.analytics.vpsLatencyInternal')
              }
            />
          </SectionCard>

          <SectionCard title={t('admin.analytics.vpsNodeTitle')}>
            <div className="space-y-2">
              <MetricRow label={t('admin.analytics.vpsNodeVersion')} value={metrics.node.version} />
              <MetricRow label={t('admin.analytics.vpsNodePid')} value={String(metrics.node.pid)} />
            </div>
          </SectionCard>

          {metrics.warnings.length > 0 && (
            <ul className="text-[10px] text-gray-500 space-y-1 px-1">
              {metrics.warnings.map((w, i) => (
                <li key={i}>• {w}</li>
              ))}
            </ul>
          )}
        </>
      )}

      <AnalyticsSyslogSection />
    </div>
  );
}

﻿import { useCallback, useEffect, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../context/AuthContext';
import { MsdevDualIpPanel } from '../components/MsdevDualIpPanel';
import { LegalDocumentView } from '../components/LegalDocumentView';
import { CURRENT_TERMS_VERSION, type LegalKey } from '../content/legal';
import { peekPendingSalonJoin } from '../lib/salonDeepLink';
import { forgotPasswordHref } from '../lib/forgotPasswordRoute';
import { api } from '../lib/api';
import { isNativeIos } from '../lib/nativePlatform';
import { SoundyLogo } from '../components/SoundyLogo';
import { PasswordStrengthBar } from '../components/PasswordStrengthBar';
import { getPasswordStrengthAsync, preloadPasswordStrength } from '../lib/passwordStrength';
import type { PublicAccessConfig, User } from '../types';
import { startAuthentication } from '@simplewebauthn/browser';

// ─── OAuth provider status ───────────────────────────────────────────────────

const OAUTH_ERROR_MESSAGES: Record<string, (provider: string) => string> = {
  not_configured: (p) => `La connexion via ${p} n'est pas encore activée.`,
  cancelled:      (p) => `Connexion ${p} annulée.`,
  invalid_state:  ()  => `Requête OAuth expirée. Veuillez réessayer.`,
  server_error:   (p) => `Erreur lors de la connexion ${p}. Veuillez réessayer.`,
  registration_denied: () => 'Inscription refusée. Les inscriptions sont peut-être fermées ou sur invitation.',
  account_pending: () => 'Votre compte est en attente de validation par un administrateur.',
  account_blocked: () => 'Votre compte a été suspendu. Contactez l’administrateur.',
};

function oauthErrorMessage(code: string, provider: string): string {
  const label = provider === 'google' ? 'Google' : provider === 'apple' ? 'Apple' : provider;
  const fn = OAUTH_ERROR_MESSAGES[code];
  return fn ? fn(label) : `Erreur de connexion ${label}.`;
}

// ─── Password strength ────────────────────────────────────────────────────────
// See src/components/PasswordStrengthBar.tsx and src/lib/passwordStrength.ts

export function AuthPage() {
  const { t } = useTranslation();
  const { register, setSession, token } = useAuth();
  const handleAutoLogin = useCallback(
    (t: string, u: User) => { setSession(t, u); },
    [setSession]
  );
  const [mode, setMode] = useState<'login' | 'register'>('login');

  // ── 2FA challenge state ────────────────────────────────────────────────────
  const [twoFAState, setTwoFAState] = useState<{ tempToken: string; rememberMe: boolean } | null>(null);
  const [twoFACode, setTwoFACode] = useState('');
  const [twoFALoading, setTwoFALoading] = useState(false);
  const [twoFAError, setTwoFAError] = useState('');
  const isMsdev = import.meta.env.VITE_APP_ENV === 'msdev';
  const [email, setEmail] = useState(isMsdev ? 'listener@msdev.local' : '');
  const [password, setPassword] = useState(isMsdev ? 'msdev123' : '');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [username, setUsername] = useState('');
  const [acceptTerms, setAcceptTerms] = useState(false);
  const [confirmAge, setConfirmAge] = useState(false);
  const [rememberMe, setRememberMe] = useState(true);
  const [inviteCode, setInviteCode] = useState('');
  const [accessConfig, setAccessConfig] = useState<PublicAccessConfig | null>(null);
  const [registerSuccess, setRegisterSuccess] = useState('');
  const [legalPreview, setLegalPreview] = useState<LegalKey | null>(null);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const pendingSalonId = peekPendingSalonJoin();

  const [usernameStatus, setUsernameStatus] = useState<'idle' | 'checking' | 'available' | 'taken' | 'invalid'>('idle');
  const [usernameMessage, setUsernameMessage] = useState('');
  const usernameTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [oauthLoading, setOauthLoading] = useState(false);
  const [googleOAuthAvailable, setGoogleOAuthAvailable] = useState(false);
  const [appleOAuthAvailable, setAppleOAuthAvailable] = useState(false);
  const [oauthTermsCode, setOauthTermsCode] = useState<string | null>(null);
  const [oauthAcceptTerms, setOauthAcceptTerms] = useState(false);
  const [oauthConfirmAge, setOauthConfirmAge] = useState(false);
  const [oauthTermsBusy, setOauthTermsBusy] = useState(false);

  // ── Biometric / Face ID ───────────────────────────────────────────────────
  const [biometricSupported, setBiometricSupported] = useState(false);
  const [biometricLoading, setBiometricLoading]     = useState(false);

  const checkUsername = useCallback((value: string) => {
    if (usernameTimer.current) clearTimeout(usernameTimer.current);
    if (!value || value.length < 2) {
      setUsernameStatus('idle');
      setUsernameMessage('');
      return;
    }
    setUsernameStatus('checking');
    usernameTimer.current = setTimeout(async () => {
      try {
        const res = await api.checkUsername(value);
        if (res.available) {
          setUsernameStatus('available');
          setUsernameMessage('Pseudo disponible');
        } else {
          setUsernameStatus('taken');
          setUsernameMessage(res.reason ?? 'Pseudo non disponible');
        }
      } catch {
        setUsernameStatus('idle');
        setUsernameMessage('');
      }
    }, 400);
  }, []);

  useEffect(() => {
    api.getAccessConfig().then(setAccessConfig).catch(() => {});
    api.getOAuthProviders().then((p) => {
      setGoogleOAuthAvailable(p.google);
      setAppleOAuthAvailable(p.apple);
    }).catch(() => {});

    // Vérifie si la biométrie est disponible sur cet appareil/navigateur
    if (
      typeof window !== 'undefined' &&
      typeof window.PublicKeyCredential !== 'undefined' &&
      typeof window.PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable === 'function'
    ) {
      window.PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable()
        .then(setBiometricSupported)
        .catch(() => setBiometricSupported(false));
    }
  }, []);

  useEffect(() => {
    if (mode === 'register') void preloadPasswordStrength();
  }, [mode]);

  // Handle OAuth callback: backend redirects to /?oauth_code=… after Google auth.
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const oauthCode = params.get('oauth_code');
    const isNewUser    = params.get('new_user') === '1';
    const oauthErrCode = params.get('oauth_error');
    const provider     = params.get('provider') ?? '';
    const oauthPending = params.get('oauth_pending') === '1';
    const needsTerms   = params.get('needs_terms') === '1';

    const stripOAuthParams = () => {
      params.delete('oauth_code');
      params.delete('new_user');
      params.delete('oauth_error');
      params.delete('provider');
      params.delete('oauth_pending');
      params.delete('needs_terms');
      const q = params.toString();
      window.history.replaceState({}, '', `${window.location.pathname}${q ? `?${q}` : ''}`);
    };

    if (oauthPending) {
      setRegisterSuccess(
        'Inscription enregistrée. Un administrateur doit valider votre compte avant la première connexion.'
      );
      setMode('login');
      stripOAuthParams();
      return;
    }

    if (oauthErrCode) {
      setError(oauthErrorMessage(oauthErrCode, provider));
      stripOAuthParams();
      return;
    }

    if (!oauthCode) return;

    if (needsTerms) {
      setOauthTermsCode(oauthCode);
      stripOAuthParams();
      return;
    }

    stripOAuthParams();
    setOauthLoading(true);
    api.exchangeOAuthCode(oauthCode)
      .then((r) => {
        if (r.pending) {
          setRegisterSuccess(
            r.message ||
              'Inscription enregistrée. Un administrateur doit valider votre compte avant la première connexion.'
          );
          setMode('login');
          setOauthLoading(false);
          return;
        }
        if (!r.token || !r.user) {
          throw new Error('Réponse OAuth invalide');
        }
        setSession(r.token, r.user, true, isNewUser || r.isNew);
      })
      .catch((err) => {
        const msg = err instanceof Error ? err.message : 'Connexion sociale échouée.';
        if (msg.includes('CGU') || msg.includes('Politique')) {
          setOauthTermsCode(oauthCode);
          setOauthLoading(false);
          return;
        }
        setError(msg.includes('expiré') || msg.includes('invalide') ? 'Connexion sociale échouée. Le code est invalide ou expiré.' : msg);
        setOauthLoading(false);
      });
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const completeOAuthTerms = async () => {
    if (!oauthTermsCode || !oauthConfirmAge) {
      setError("Vous devez confirmer que vous avez au moins 13 ans");
      return;
    }
    if (!oauthAcceptTerms) {
      setError('Vous devez accepter les CGU et la Politique de confidentialité');
      return;
    }
    setOauthTermsBusy(true);
    setError('');
    try {
      const r = await api.exchangeOAuthCode(oauthTermsCode, {
        acceptTerms: true,
        termsVersion: CURRENT_TERMS_VERSION,
        confirmAge: true,
      });
      if (r.pending) {
        setRegisterSuccess(
          r.message ||
            'Inscription enregistrée. Un administrateur doit valider votre compte avant la première connexion.'
        );
        setOauthTermsCode(null);
        setMode('login');
        return;
      }
      if (!r.token || !r.user) throw new Error('Réponse OAuth invalide');
      setSession(r.token, r.user, true, true);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Connexion sociale échouée.');
    } finally {
      setOauthTermsBusy(false);
    }
  };

  useEffect(() => {
    return () => { if (usernameTimer.current) clearTimeout(usernameTimer.current); };
  }, []);

  const handleBiometricLogin = async () => {
    setError('');
    setBiometricLoading(true);
    try {
      const options = await api.webauthnLoginOptions();
      const { sessionId, ...authOptions } = options;
      const authResponse = await startAuthentication({ optionsJSON: authOptions });
      const result = await api.webauthnLoginVerify(sessionId, authResponse);
      setSession(result.token, result.user, true, false);
    } catch (err) {
      if (err instanceof Error) {
        if (err.name === 'NotAllowedError') {
          setError(t('auth.biometricLoginLoading') + ' — annulé.');
        } else if ((err as { code?: string }).code === 'webauthn_credential_not_found') {
          setError(t('auth.biometricNotRegistered'));
        } else {
          setError(err.message || t('auth.biometricNotSupported'));
        }
      } else {
        setError(t('auth.biometricNotSupported'));
      }
    } finally {
      setBiometricLoading(false);
    }
  };

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setRegisterSuccess('');

    if (mode === 'register') {
      if (accessConfig?.registrationClosed && accessConfig.registrationMode === 'closed') {
        setError('Les inscriptions sont fermées. Demandez une invitation à l’administrateur.');
        return;
      }
      if (!confirmAge) {
        setError("Vous devez confirmer que vous avez au moins 13 ans");
        return;
      }
      if (!acceptTerms) {
        setError('Vous devez accepter les CGU et la Politique de confidentialité');
        return;
      }
      if (username.trim().length < 2) {
        setError('Le pseudo doit faire au moins 2 caractères');
        return;
      }
      if (usernameStatus === 'taken') {
        setError(usernameMessage || 'Ce pseudo est déjà pris');
        return;
      }
      if (!email.includes('@') || !email.includes('.')) {
        setError('Adresse e-mail invalide');
        return;
      }
      if (password.length < 8) {
        setError('Le mot de passe doit contenir au moins 8 caractères');
        return;
      }
      if (password !== confirmPassword) {
        setError('Les mots de passe ne correspondent pas');
        return;
      }
      if ((await getPasswordStrengthAsync(password)) === 'faible') {
        setError('Mot de passe trop faible. Ajoutez des chiffres, majuscules ou symboles');
        return;
      }
      if (accessConfig?.inviteRequired && !inviteCode.trim()) {
        setError('Code d’invitation requis pour créer un compte.');
        return;
      }
    }

    setLoading(true);
    try {
      if (mode === 'login') {
        const r = await api.login(email, password, rememberMe);
        if (r.requires2FA && r.tempToken) {
          setTwoFAState({ tempToken: r.tempToken, rememberMe });
          return;
        }
        if (r.token && r.user) {
          setSession(r.token, r.user, rememberMe);
        }
      } else {
        const verification = await register(
          username.trim(),
          email,
          password,
          true,
          CURRENT_TERMS_VERSION,
          inviteCode.trim(),
          confirmAge
        );
        if (verification?.emailVerificationRequired) {
          setRegisterSuccess(verification.message);
          setMode('login');
        }
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Erreur inconnue';
      if (mode === 'register' && msg.includes('validation')) {
        setRegisterSuccess(msg);
        setMode('login');
      } else {
        setError(msg);
      }
    } finally {
      setLoading(false);
    }
  };

  const submitTwoFA = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!twoFAState || !twoFACode) return;
    setTwoFAError('');
    setTwoFALoading(true);
    try {
      const r = await api.validate2FA(twoFAState.tempToken, twoFACode);
      setSession(r.token, r.user, twoFAState.rememberMe);
    } catch (err) {
      setTwoFAError(err instanceof Error ? err.message : 'Code invalide');
    } finally {
      setTwoFALoading(false);
    }
  };

  // ── 2FA challenge screen ─────────────────────────────────────────────────
  if (twoFAState) {
    return (
      <div className="min-h-dvh flex flex-col items-center justify-center p-6 bg-[#0b0b0f]">
        <div className="w-full max-w-sm">
          <div className="text-center mb-8">
            <div className="inline-flex w-14 h-14 rounded-2xl bg-gradient-to-tr from-purple-600 to-pink-500 items-center justify-center text-2xl mb-4">
              🔐
            </div>
            <h1 className="text-2xl font-extrabold text-white">Vérification</h1>
            <p className="text-gray-400 text-sm mt-2">Double authentification</p>
          </div>

          <form onSubmit={submitTwoFA} className="space-y-4 bg-[#12121a] border border-[#1e1e2f] rounded-2xl p-6">
            <p className="text-sm text-gray-300 text-center leading-relaxed">
              Entrez le code à 6 chiffres de votre application d'authentification.
            </p>

            <input
              className="w-full bg-[#1a1a26] border border-[#2d2d3d] rounded-xl px-4 py-3 text-white font-mono text-xl tracking-[0.3em] text-center"
              type="text"
              inputMode="numeric"
              placeholder="• • • • • •"
              value={twoFACode}
              onChange={(e) => setTwoFACode(e.target.value.replace(/\D/g, '').slice(0, 8))}
              maxLength={8}
              autoComplete="one-time-code"
              autoFocus
              required
            />

            <p className="text-[11px] text-gray-500 text-center">
              Ou entrez un{' '}
              <span className="text-purple-400">code de secours</span>{' '}
              (format XXXX-XXXX).
            </p>

            {twoFAError && (
              <div className="flex items-start gap-2 bg-red-500/10 border border-red-500/30 rounded-xl px-3 py-2">
                <span className="text-red-400 shrink-0 mt-0.5">⚠</span>
                <p className="text-red-400 text-sm">{twoFAError}</p>
              </div>
            )}

            <button
              type="submit"
              disabled={twoFALoading || twoFACode.length < 6}
              className="w-full py-3 rounded-xl bg-purple-600 hover:bg-purple-500 font-bold text-white disabled:opacity-50 transition"
            >
              {twoFALoading ? (
                <span className="inline-flex items-center gap-2 justify-center">
                  <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                  Vérification…
                </span>
              ) : (
                'Valider'
              )}
            </button>
          </form>

          <button
            type="button"
            className="w-full mt-3 text-center text-sm text-gray-500 hover:text-gray-400 transition"
            onClick={() => { setTwoFAState(null); setTwoFACode(''); setTwoFAError(''); }}
          >
            ← Retour à la connexion
          </button>
        </div>
      </div>
    );
  }

  if (oauthLoading) {
    return (
      <div className="min-h-dvh flex flex-col items-center justify-center gap-3 bg-[#0b0b0f] text-gray-400">
        <span className="w-8 h-8 border-2 border-purple-500/30 border-t-purple-400 rounded-full animate-spin" />
        <p className="text-sm">Connexion en cours…</p>
      </div>
    );
  }

  if (legalPreview) {
    return (
      <div className="min-h-dvh bg-[#0b0b0f]">
        <LegalDocumentView docKey={legalPreview} onBack={() => setLegalPreview(null)} />
      </div>
    );
  }

  if (oauthTermsCode) {
    return (
      <div className="min-h-dvh flex flex-col items-center justify-center p-6 bg-[#0b0b0f]">
        <div className="w-full max-w-sm bg-[#12121a] border border-[#1e1e2f] rounded-2xl p-6 space-y-4">
          <h2 className="text-lg font-bold text-white text-center">Finaliser votre inscription</h2>
          <p className="text-sm text-gray-400 text-center">
            Acceptez les conditions pour activer votre compte créé via Google.
          </p>
          <label className="flex items-start gap-2 cursor-pointer text-xs text-gray-400 leading-snug">
            <input
              type="checkbox"
              checked={oauthConfirmAge}
              onChange={(e) => setOauthConfirmAge(e.target.checked)}
              className="melosong-checkbox mt-0.5 shrink-0"
            />
            <span>{t('auth.ageConfirmCheckbox')}</span>
          </label>
          <label className="flex items-start gap-2 cursor-pointer text-xs text-gray-400 leading-snug">
            <input
              type="checkbox"
              checked={oauthAcceptTerms}
              onChange={(e) => setOauthAcceptTerms(e.target.checked)}
              className="melosong-checkbox mt-0.5 shrink-0"
            />
            <span>
              {t('auth.acceptTermsPrefix')}{' '}
              <button type="button" className="text-purple-400 underline" onClick={() => setLegalPreview('terms')}>
                {t('auth.termsLink')}
              </button>{' '}
              {t('auth.acceptTermsAnd')}{' '}
              <button type="button" className="text-purple-400 underline" onClick={() => setLegalPreview('privacy')}>
                {t('auth.privacyLink')}
              </button>{' '}
              (v.{CURRENT_TERMS_VERSION})
            </span>
          </label>
          {error && <p className="text-sm text-red-400">{error}</p>}
          <button
            type="button"
            disabled={oauthTermsBusy || !oauthAcceptTerms || !oauthConfirmAge}
            onClick={() => void completeOAuthTerms()}
            className="w-full py-3 rounded-xl bg-purple-600 hover:bg-purple-500 font-bold text-white disabled:opacity-50 transition"
          >
            {oauthTermsBusy ? 'Validation…' : 'Continuer'}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-dvh flex flex-col items-center justify-center p-6 bg-[#0b0b0f]">
      <div className="w-full max-w-sm">
        <div className="text-center mb-8">
          <SoundyLogo className="h-12 sm:h-14 w-auto mx-auto mb-4" />
          <p className="text-gray-400 text-sm mt-2">{t('app.tagline')}</p>
        </div>

        {pendingSalonId && (
          <p className="mb-4 text-center text-xs text-purple-300 bg-purple-500/10 border border-purple-500/30 rounded-xl px-4 py-3">
            {t('auth.pendingSalon')}
          </p>
        )}

        {accessConfig?.enabled && (
          <p className="mb-4 text-center text-xs text-amber-200/90 bg-amber-500/10 border border-amber-500/30 rounded-xl px-4 py-3">
            {t('auth.secureAccess')}
            {accessConfig.adminApprovalRequired && t('auth.adminApproval')}
          </p>
        )}

        {registerSuccess && (
          <p className="mb-4 text-center text-xs text-green-300 bg-green-500/10 border border-green-500/30 rounded-xl px-4 py-3">
            {registerSuccess}
          </p>
        )}

        <form onSubmit={submit} className="space-y-4 bg-[#12121a] border border-[#1e1e2f] rounded-2xl p-6">
          {mode === 'register' && (
            <div className="space-y-1">
              <div className="relative">
                <input
                  className="w-full bg-[#1a1a26] border border-[#2d2d3d] rounded-xl px-4 py-3 text-white pr-9"
                  placeholder={t('auth.username')}
                  value={username}
                  onChange={(e) => {
                    setUsername(e.target.value);
                    checkUsername(e.target.value);
                  }}
                  required
                  autoComplete="username"
                />
                {usernameStatus === 'checking' && (
                  <span className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 border-2 border-purple-500/30 border-t-purple-400 rounded-full animate-spin" />
                )}
                {usernameStatus === 'available' && (
                  <span className="absolute right-3 top-1/2 -translate-y-1/2 text-green-400 text-sm">✓</span>
                )}
                {usernameStatus === 'taken' && (
                  <span className="absolute right-3 top-1/2 -translate-y-1/2 text-red-400 text-sm">✗</span>
                )}
              </div>
              {usernameMessage && (
                <p className={`text-[11px] ${usernameStatus === 'available' ? 'text-green-400' : 'text-red-400'}`}>
                  {usernameMessage}
                </p>
              )}
            </div>
          )}

          {mode === 'register' && accessConfig?.inviteRequired && (
            <input
              className="w-full bg-[#1a1a26] border border-[#2d2d3d] rounded-xl px-4 py-3 text-white font-mono uppercase"
              placeholder="Code d’invitation"
              value={inviteCode}
              onChange={(e) => setInviteCode(e.target.value)}
              required
              autoComplete="off"
            />
          )}

          <input
            className="w-full bg-[#1a1a26] border border-[#2d2d3d] rounded-xl px-4 py-3 text-white"
            type="email"
            placeholder={t('auth.email')}
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
            autoComplete="email"
          />

          <div className="space-y-2">
            <input
              className="w-full bg-[#1a1a26] border border-[#2d2d3d] rounded-xl px-4 py-3 text-white"
              type="password"
              placeholder={t('auth.password')}
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              autoComplete={mode === 'login' ? 'current-password' : 'new-password'}
            />
            {mode === 'login' && (
              <div className="flex justify-end">
                <a
                  href={forgotPasswordHref()}
                  className="text-xs text-purple-400 hover:text-purple-300 underline transition"
                >
                  {t('auth.forgotPassword')}
                </a>
              </div>
            )}
            {mode === 'register' && <PasswordStrengthBar password={password} />}
          </div>

          {mode === 'register' && (
            <input
              className="w-full bg-[#1a1a26] border border-[#2d2d3d] rounded-xl px-4 py-3 text-white"
              type="password"
              placeholder={t('auth.confirmPassword')}
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              required
              autoComplete="new-password"
            />
          )}

          {mode === 'register' && confirmPassword && password !== confirmPassword && (
            <p className="text-[11px] text-red-400">{t('auth.passwordMismatch')}</p>
          )}

          {mode === 'register' && accessConfig?.inviteRequired && (
            <input
              className="w-full bg-[#1a1a26] border border-[#2d2d3d] rounded-xl px-4 py-3 text-white"
              type="text"
              placeholder={t('auth.inviteCode')}
              value={inviteCode}
              onChange={(e) => setInviteCode(e.target.value)}
              autoComplete="off"
            />
          )}

          {mode === 'login' && (
            <label className="flex items-start gap-2 cursor-pointer">
              <input
                type="checkbox"
                checked={rememberMe}
                onChange={(e) => setRememberMe(e.target.checked)}
                className="melosong-checkbox mt-0.5 shrink-0"
              />
              <span className="text-xs text-gray-400 leading-snug">
                {t('auth.rememberMe')}
                <span className="block text-[10px] text-gray-500 mt-0.5">
                  {t('auth.rememberMeHint')}
                </span>
              </span>
            </label>
          )}

          {mode === 'register' && (
            <label className="flex items-start gap-2 cursor-pointer text-xs text-gray-400 leading-snug">
              <input
                type="checkbox"
                checked={confirmAge}
                onChange={(e) => setConfirmAge(e.target.checked)}
                className="melosong-checkbox mt-0.5 shrink-0"
                required
              />
              <span>{t('auth.ageConfirmCheckbox')}</span>
            </label>
          )}

          {mode === 'register' && (
            <label className="flex items-start gap-2 cursor-pointer text-xs text-gray-400 leading-snug">
              <input
                type="checkbox"
                checked={acceptTerms}
                onChange={(e) => setAcceptTerms(e.target.checked)}
                className="melosong-checkbox mt-0.5 shrink-0"
                required
              />
              <span>
                {t('auth.acceptTermsPrefix')}{' '}
                <button type="button" className="text-purple-400 underline" onClick={() => setLegalPreview('terms')}>
                  {t('auth.termsLink')}
                </button>{' '}
                {t('auth.acceptTermsAnd')}{' '}
                <button type="button" className="text-purple-400 underline" onClick={() => setLegalPreview('privacy')}>
                  {t('auth.privacyLink')}
                </button>{' '}
                (v.{CURRENT_TERMS_VERSION})
              </span>
            </label>
          )}

          {mode === 'register' && (
            <p className="text-[10px] text-gray-500 leading-snug">{t('auth.minAgeNotice')}</p>
          )}

          {error && (
            <div className="flex items-start gap-2 bg-red-500/10 border border-red-500/30 rounded-xl px-3 py-2">
              <span className="text-red-400 shrink-0 mt-0.5">⚠</span>
              <p className="text-red-400 text-sm">{error}</p>
            </div>
          )}

          {registerSuccess && (
            <div className="flex items-start gap-2 bg-green-500/10 border border-green-500/30 rounded-xl px-3 py-2">
              <span className="text-green-400 shrink-0 mt-0.5">✓</span>
              <p className="text-green-400 text-sm">{registerSuccess}</p>
            </div>
          )}

          <button
            type="submit"
            disabled={loading || (mode === 'register' && (!acceptTerms || !confirmAge))}
            className="w-full py-3 rounded-xl bg-purple-600 hover:bg-purple-500 font-bold text-white disabled:opacity-50 transition"
          >
            {loading ? (
              <span className="inline-flex items-center gap-2 justify-center">
                <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                {mode === 'login' ? t('auth.submitLoginLoading') : t('auth.submitRegisterLoading')}
              </span>
            ) : (
              mode === 'login' ? t('auth.submitLogin') : t('auth.submitRegister')
            )}
          </button>
        </form>

        {(appleOAuthAvailable || (googleOAuthAvailable && !(isNativeIos() && !appleOAuthAvailable))) && (
        <div className="mt-3 space-y-3">
          <div className="flex items-center gap-3">
            <div className="h-px flex-1 bg-[#1e1e2f]" />
            <span className="text-[11px] text-gray-500 shrink-0">{t('auth.oauthOrContinue')}</span>
            <div className="h-px flex-1 bg-[#1e1e2f]" />
          </div>

          {appleOAuthAvailable && (
            <button
              type="button"
              onClick={() => { window.location.href = '/api/auth/apple'; }}
              aria-describedby="apple-oauth-hint"
              className="w-full min-h-[44px] py-2.5 px-4 rounded-xl bg-black border border-[#1e1e2f] flex items-center justify-center gap-3 transition active:scale-[0.99] hover:border-purple-500/50 hover:bg-[#12121a] hover:shadow-[0_0_12px_rgba(139,92,246,0.2)] cursor-pointer"
            >
              <svg width="20" height="20" viewBox="0 0 24 24" aria-hidden="true" className="shrink-0 fill-white">
                <path d="M17.05 20.28c-.98.95-2.05.88-3.08.4-1.09-.5-2.08-.48-3.24 0-1.44.62-2.2.44-3.06-.4C2.79 15.25 3.51 7.59 9.05 7.31c1.35.07 2.29.74 3.08.8 1.18-.24 2.31-.93 3.57-.84 1.51.12 2.65.72 3.4 1.8-3.12 1.87-2.38 5.98.48 7.13-.57 1.5-1.31 2.99-2.54 4.09l.01-.01zM12.03 7.25c-.15-2.23 1.66-4.07 3.74-4.25.29 2.58-2.34 4.5-3.74 4.25z" />
              </svg>
              <span className="text-sm font-semibold text-white">{t('auth.continueWithApple')}</span>
            </button>
          )}

          {googleOAuthAvailable && !(isNativeIos() && !appleOAuthAvailable) && (
            <>
              <button
                type="button"
                onClick={() => { window.location.href = '/api/auth/google'; }}
                aria-describedby="google-oauth-hint"
                className="w-full min-h-[44px] py-2.5 px-4 rounded-xl bg-[#12121a] border border-[#1e1e2f] flex items-center justify-center gap-3 transition active:scale-[0.99] hover:border-purple-500/50 hover:bg-[#1a1a26] hover:shadow-[0_0_12px_rgba(139,92,246,0.2)] cursor-pointer"
              >
                <svg width="20" height="20" viewBox="0 0 48 48" aria-hidden="true" className="shrink-0">
                  <path fill="#EA4335" d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z"/>
                  <path fill="#4285F4" d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z"/>
                  <path fill="#FBBC05" d="M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z"/>
                  <path fill="#34A853" d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z"/>
                </svg>
                <span className="text-sm font-semibold text-white">{t('auth.continueWithGoogle')}</span>
              </button>
              <p id="google-oauth-hint" className="text-center text-[11px] text-gray-500 leading-snug">
                {t('auth.continueWithGoogleHint')}
              </p>
            </>
          )}

          {appleOAuthAvailable && (
            <p id="apple-oauth-hint" className="text-center text-[11px] text-gray-500 leading-snug">
              {t('auth.continueWithAppleHint')}
            </p>
          )}
        </div>
        )}

        {/* ── Face ID / empreinte (WebAuthn) — connexion uniquement ── */}
        {mode === 'login' && biometricSupported && (
          <div className="mt-3 space-y-3">
            <div className="flex items-center gap-3">
              <div className="h-px flex-1 bg-[#1e1e2f]" />
              <span className="text-[11px] text-gray-500 shrink-0">{t('auth.biometricOr')}</span>
              <div className="h-px flex-1 bg-[#1e1e2f]" />
            </div>
            <button
              type="button"
              disabled={biometricLoading}
              onClick={() => void handleBiometricLogin()}
              className="w-full flex items-center justify-center gap-2.5 py-3 rounded-xl bg-[#12121a] border border-[#1e1e2f] text-sm font-medium text-gray-200 hover:bg-[#1a1a26] hover:border-purple-500/40 hover:text-white transition active:scale-[0.98] disabled:opacity-50"
              aria-label={t('auth.biometricLogin')}
            >
              {biometricLoading ? (
                <>
                  <span className="w-4 h-4 border-2 border-purple-400/30 border-t-purple-400 rounded-full animate-spin" />
                  <span>{t('auth.biometricLoginLoading')}</span>
                </>
              ) : (
                <>
                  <span className="text-lg" aria-hidden>🔒</span>
                  <span>{t('auth.biometricLogin')}</span>
                </>
              )}
            </button>
          </div>
        )}

        <MsdevDualIpPanel onAutoLogin={handleAutoLogin} hasToken={Boolean(token)} />

        {import.meta.env.VITE_APP_ENV === 'msdev' && (
          <p className="mt-4 text-center text-[11px] text-gray-500 leading-relaxed">
            Compte démo msdev
            <br />
            <span className="text-gray-400 font-mono text-[10px]">listener@msdev.local</span>
            {' · '}
            <span className="text-gray-400 font-mono text-[10px]">msdev123</span>
          </p>
        )}

        {!(accessConfig?.registrationMode === 'closed' && mode === 'login') && (
        <button
          type="button"
          className="w-full mt-4 border border-purple-500/60 bg-purple-950/30 py-2.5 px-4 rounded-xl text-sm text-purple-300 font-medium hover:bg-purple-900/40 hover:border-purple-400 transition"
          onClick={() => {
            if (accessConfig?.registrationMode === 'closed') return;
            setMode(mode === 'login' ? 'register' : 'login');
            setError('');
            setRegisterSuccess('');
            setConfirmPassword('');
            setUsernameStatus('idle');
            setUsernameMessage('');
            setConfirmAge(false);
          }}
        >
          {mode === 'login'
            ? accessConfig?.registrationMode === 'closed'
              ? t('auth.registrationClosed')
              : t('auth.createAccount')
            : t('auth.alreadyRegistered')}
        </button>
        )}
      </div>
    </div>
  );
}

import { useCallback, useEffect, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../context/AuthContext';
import { api } from '../lib/api';
import { useSupportTicketUpdates } from '../hooks/useSupportTicketRealtime';
import type { SupportContactMessage, SupportThreadMessage } from '../types';

interface ContactSoundyPageProps {
  onBack: () => void;
  highlightMessageId?: string;
  /** Renders content only (no header/scroll shell) for embedding in SettingsPage. */
  embedded?: boolean;
}

function formatDateTime(ts: number, locale: string): string {
  return new Date(ts).toLocaleString(locale, {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
}

function getThread(msg: SupportContactMessage): SupportThreadMessage[] {
  if (msg.thread && msg.thread.length > 0) return msg.thread;
  const thread: SupportThreadMessage[] = [
    {
      id: `${msg.id}_u0`,
      role: 'user',
      body: msg.body,
      createdAt: msg.createdAt,
      authorUserId: msg.fromUserId,
    },
  ];
  if (msg.adminReply && msg.repliedAt) {
    thread.push({
      id: `${msg.id}_a0`,
      role: 'admin',
      body: msg.adminReply,
      createdAt: msg.repliedAt,
      authorUserId: 'admin',
    });
  }
  if (msg.userReply && msg.userRepliedAt) {
    thread.push({
      id: `${msg.id}_u1`,
      role: 'user',
      body: msg.userReply,
      createdAt: msg.userRepliedAt,
      authorUserId: msg.fromUserId,
    });
  }
  return thread;
}

export function ContactSoundyPage({ onBack, highlightMessageId, embedded }: ContactSoundyPageProps) {
  const { token } = useAuth();
  const { t, i18n } = useTranslation();
  const [body, setBody] = useState('');
  const [sending, setSending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [toast, setToast] = useState<string | null>(null);
  const [history, setHistory] = useState<SupportContactMessage[]>([]);
  const [loadingHistory, setLoadingHistory] = useState(true);
  const [replyDrafts, setReplyDrafts] = useState<Record<string, string>>({});
  const [replyingId, setReplyingId] = useState<string | null>(null);
  const [resolvingId, setResolvingId] = useState<string | null>(null);
  const toastTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const highlightRef = useRef<HTMLDivElement | null>(null);

  const showToast = useCallback((msg: string) => {
    setToast(msg);
    if (toastTimer.current) clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(null), 2500);
  }, []);

  const loadHistory = useCallback(async () => {
    if (!token) return;
    setLoadingHistory(true);
    try {
      const res = await api.getMySupportMessages(token);
      setHistory(res.messages);
    } catch {
      /* ignore */
    } finally {
      setLoadingHistory(false);
    }
  }, [token]);

  useEffect(() => {
    void loadHistory();
  }, [loadHistory]);

  const handleRealtimeUpdate = useCallback(
    (updated: SupportContactMessage) => {
      setHistory((prev) => {
        const idx = prev.findIndex((m) => m.id === updated.id);
        if (idx === -1) {
          if (updated.status === 'resolved') return prev;
          return [updated, ...prev];
        }
        const next = [...prev];
        next[idx] = updated;
        return next;
      });
      if (updated.status === 'resolved') {
        showToast(t('support.resolvedByAdmin'));
      }
    },
    [showToast, t]
  );

  useSupportTicketUpdates(handleRealtimeUpdate, Boolean(token));

  useEffect(() => {
    if (!highlightMessageId || loadingHistory) return;
    highlightRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }, [highlightMessageId, loadingHistory, history.length]);

  const submit = async () => {
    if (!token) return;
    const text = body.trim();
    if (text.length < 3) return;
    setSending(true);
    setError(null);
    try {
      await api.submitSupportContact(token, text);
      setBody('');
      showToast(t('support.sent'));
      await loadHistory();
    } catch (e) {
      setError(e instanceof Error ? e.message : t('support.sendError'));
    } finally {
      setSending(false);
    }
  };

  const sendThreadReply = async (msg: SupportContactMessage) => {
    if (!token) return;
    const text = (replyDrafts[msg.id] ?? '').trim();
    if (text.length < 3) return;
    setReplyingId(msg.id);
    setError(null);
    try {
      await api.replySupportContact(token, msg.id, text);
      setReplyDrafts((prev) => ({ ...prev, [msg.id]: '' }));
      showToast(t('support.replySent'));
      await loadHistory();
    } catch (e) {
      setError(e instanceof Error ? e.message : t('support.replyError'));
    } finally {
      setReplyingId(null);
    }
  };

  const markResolved = async (msg: SupportContactMessage) => {
    if (!token) return;
    setResolvingId(msg.id);
    setError(null);
    try {
      await api.resolveSupportContact(token, msg.id);
      showToast(t('support.resolved'));
      await loadHistory();
    } catch (e) {
      setError(e instanceof Error ? e.message : t('support.resolveError'));
    } finally {
      setResolvingId(null);
    }
  };

  const content = (
    <div className={`${embedded ? '' : 'flex-1 '}p-4 max-w-lg mx-auto w-full space-y-4`}>
        <p className="text-sm text-gray-400">{t('support.intro')}</p>

        <label className="block">
          <span className="text-xs text-gray-400">{t('support.messageLabel')}</span>
          <textarea
            value={body}
            onChange={(e) => setBody(e.target.value)}
            rows={6}
            maxLength={4000}
            placeholder={t('support.messagePlaceholder')}
            className="mt-1 w-full bg-[#1a1a26] border border-[#2d2d3d] rounded-xl px-3 py-2 text-white text-sm"
          />
        </label>

        {error && <p className="text-sm text-red-400">{error}</p>}

        <button
          type="button"
          onClick={() => void submit()}
          disabled={sending || body.trim().length < 3}
          className="w-full py-3 rounded-xl bg-purple-600 hover:bg-purple-500 text-white font-bold disabled:opacity-50"
        >
          {sending ? t('support.sending') : t('support.send')}
        </button>

        {history.length > 0 && (
          <section className="pt-2 space-y-3">
            <h2 className="text-sm font-bold text-gray-300">{t('support.historyTitle')}</h2>
            {loadingHistory ? (
              <p className="text-xs text-gray-500">{t('support.loading')}</p>
            ) : (
              history.map((msg) => {
                const thread = getThread(msg);
                const isHighlighted = msg.id === highlightMessageId;
                const canReplyOrResolve = msg.status === 'replied';

                return (
                  <div
                    key={msg.id}
                    ref={isHighlighted ? highlightRef : undefined}
                    className={`rounded-xl border p-3 space-y-2 ${
                      isHighlighted
                        ? 'border-purple-500/60 bg-purple-950/20'
                        : 'border-[#2d2d3d] bg-[#12121a]'
                    }`}
                  >
                    {msg.status === 'resolved' && (
                      <div className="rounded-lg bg-green-950/30 border border-green-500/30 px-3 py-2 space-y-1">
                        <p className="text-[10px] font-bold text-green-400/90">{t('support.statusResolved')}</p>
                        <p className="text-xs text-green-200/90">{t('support.resolvedByAdmin')}</p>
                      </div>
                    )}
                    <div className="space-y-3">
                      {thread.map((entry) => (
                        <div
                          key={entry.id}
                          className={
                            entry.role === 'admin' ? 'pt-2 border-t border-[#2d2d3d]' : undefined
                          }
                        >
                          <p className="text-xs font-semibold text-purple-300">
                            {entry.role === 'admin' ? t('support.replyLabel') : t('support.youLabel')}
                          </p>
                          <p className="text-[10px] text-gray-500">
                            {formatDateTime(entry.createdAt, i18n.language)}
                          </p>
                          <p className="text-sm text-gray-200 whitespace-pre-wrap mt-1">{entry.body}</p>
                        </div>
                      ))}
                    </div>
                    {msg.status === 'open' && !msg.adminReply && (
                      <p className="text-[10px] text-amber-400/90">{t('support.pending')}</p>
                    )}
                    {msg.status === 'open' && msg.adminReply && (
                      <p className="text-[10px] text-amber-400/90">{t('support.awaitingAdmin')}</p>
                    )}
                    {canReplyOrResolve && (
                      <div className="pt-2 border-t border-[#2d2d3d] space-y-2">
                        <label className="block">
                          <span className="text-xs text-gray-400">{t('support.followUpLabel')}</span>
                          <textarea
                            value={replyDrafts[msg.id] ?? ''}
                            onChange={(e) =>
                              setReplyDrafts((prev) => ({ ...prev, [msg.id]: e.target.value }))
                            }
                            rows={3}
                            maxLength={4000}
                            placeholder={t('support.followUpPlaceholder')}
                            className="mt-1 w-full bg-[#1a1a26] border border-[#2d2d3d] rounded-xl px-3 py-2 text-white text-sm"
                          />
                        </label>
                        <div className="flex gap-2">
                          <button
                            type="button"
                            onClick={() => void sendThreadReply(msg)}
                            disabled={
                              replyingId === msg.id || (replyDrafts[msg.id] ?? '').trim().length < 3
                            }
                            className="flex-1 py-2.5 rounded-xl bg-purple-600 text-white font-bold text-sm disabled:opacity-50"
                          >
                            {replyingId === msg.id ? t('support.replying') : t('support.reply')}
                          </button>
                          <button
                            type="button"
                            onClick={() => void markResolved(msg)}
                            disabled={resolvingId === msg.id}
                            className="flex-1 py-2.5 rounded-xl bg-green-700 hover:bg-green-600 text-white font-bold text-sm disabled:opacity-50"
                          >
                            {resolvingId === msg.id ? t('support.resolving') : t('support.resolvedButton')}
                          </button>
                        </div>
                      </div>
                    )}
                  </div>
                );
              })
            )}
          </section>
        )}
      </div>
  );

  const toastEl = toast && (
    <div className="fixed bottom-24 left-4 right-4 z-[80] mx-auto max-w-sm pointer-events-none">
      <div className="rounded-xl bg-green-900/90 border border-green-500/40 px-4 py-3 text-center text-sm text-green-100 shadow-xl">
        {toast}
      </div>
    </div>
  );

  if (embedded) {
    return (
      <>
        {content}
        {toastEl}
      </>
    );
  }

  return (
    <div className="flex flex-col h-full min-h-0 bg-[#0b0b0f] text-white">
      <header className="sticky top-0 z-10 shrink-0 flex items-center gap-3 px-4 py-3 border-b border-[#1e1e2f] bg-[#0b0b0f]/95 backdrop-blur ms-safe-area-top">
        <button
          type="button"
          onClick={onBack}
          className="shrink-0 w-11 h-11 flex items-center justify-center rounded-full bg-[#1a1a26]/80 border border-[#2d2d3d] text-gray-400 hover:text-white hover:border-[#3d3d50] transition active:scale-95"
          aria-label={t('common.back')}
        >
          <svg viewBox="0 0 24 24" className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2.5">
            <path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7" />
          </svg>
        </button>
        <h1 className="flex-1 min-w-0 text-lg font-bold truncate">{t('support.title')}</h1>
      </header>
      <div className="flex-1 min-h-0 overflow-y-auto overscroll-contain">
        {content}
      </div>
      {toastEl}
    </div>
  );
}

