          setUserPosition(sanitizeLatLngTuple(coords[0], coords[1]));
          setSafeCenter(coords);
          loadNearby(coords[0], coords[1]);
          setLocating(false);
        },
        () => {
          setLocating(false);
          setSafeCenter([geo.latitude, geo.longitude]);
