          <button
            type="button"
            onClick={leaveLive}
            className="ml-auto flex items-center px-3 py-1.5 bg-[#1a1a26] border border-[#232330] rounded-full text-xs text-gray-300 font-bold hover:text-white transition min-h-[36px]"
          >
