        chatHidden={chatHidden}
        onToggleChat={toggleChatHidden}
        chatTitle={t('live.publicChat')}
        chatMinimized={chatMinimized}
        onToggleMinimize={() => setChatMinimized((m) => !m)}
        stageFooter={isHost ? (
          <>
            <input
              ref={videoFileInputRef}
              type="file"
              accept="video/*,.mp4,.webm,.mov,.m4v"
              className="sr-only"
              aria-hidden
