          </>
        ) : undefined}
        chatHeaderExtra={
          <>
            {isHost ? (
              <LiveHostActionsPopover
                liveId={liveId}
                goalStats={goalStats}
                onOpenDonPanel={(subTab) => openHostPanel('don', subTab)}
              />
            ) : null}
            {(isHost || isDevModerator) ? (
              <LiveVipModeratorsPopover
                vipEntries={vipEntries}
                chatParticipants={chatParticipants}
                onSetVip={setVipModerator}
